    const componentWalls = new Map<string, string[]>(); // compRootWallId -> all wall ids in the component
    // Union-find to group walls by connected component (undirected connectivity through shared nodes).
    const parent = new Map<string, string>();
    const find = (id: string): string => {
      let p = parent.get(id) ?? id;
      if (p === id) return id;
      const r = find(p);
      parent.set(id, r);
      return r;
    };
    const union = (a: string, b: string) => {
      const ra = find(a), rb = find(b);
      if (ra !== rb) parent.set(ra, rb);
    };
    for (const w of walls) parent.set(w.id, w.id);
    for (const w of walls) {
      const sn = wallStartNode.get(w.id)!;
      const en = wallEndNode.get(w.id)!;
      for (const other of (startsAt.get(sn) ?? [])) union(w.id, other);
      for (const other of (endsAt.get(sn) ?? [])) union(w.id, other);
      for (const other of (startsAt.get(en) ?? [])) union(w.id, other);
      for (const other of (endsAt.get(en) ?? [])) union(w.id, other);
    }
