  const [keywords, setKeywords] = useState("");
  /** Present ▸ Upload PDF — library-relative path of the walkthrough / video brief; saved as settings.walkthrough. */
  const [walkthroughPath, setWalkthroughPath] = useState<string | undefined>(undefined);
  // Export JSON → download / local Library / Cloud Library. Opened by the toolbar button.
  const [exportJsonOpen, setExportJsonOpen] = useState(false);
  // Files ▸ Inspect → read-only listing of the Cloudflare R2 bucket as a folder hierarchy.
  /** Files ▸ Import… / Export… — the one button each opens a picker of what kind (FilePickerDialog). */
  const [importPickerOpen, setImportPickerOpen] = useState(false);
  const [exportPickerOpen, setExportPickerOpen] = useState(false);
  const underlayInputRef = useRef<HTMLInputElement | null>(null);
  // Files ▸ Import Moodboard — pick from a moodboard/1 board; only the picks land on `model.moodboards`.
  const [moodboardOpen, setMoodboardOpen] = useState(false);
  /** Board the bridge's open_moodboard_picker asked for (file under Moodboards/); cleared on close. */
  const [moodboardInitial, setMoodboardInitial] = useState<string | undefined>(undefined);
  // ── Levels (storeys), Option B — see ./levels.ts. `history` holds ONLY the active level, so every tool
  // keeps seeing one floor. The other levels live here: their model (drawn stacked in 3D, written on save /
  // export) and their parked undo stack. `levelMeta` empty = a single-level plan, as every file used to be.
  const [levelMeta, setLevelMeta] = useState<LevelMeta[]>([]);
  /** "All" level tab: 3D stacks every storey. Off = 3D shows only the active level. 2D is unaffected either way. */
  const [show3dAllLevels, setShow3dAllLevels] = useState(false);
  /** "All" draws each storey as its SHELL (exterior walls, openings, slabs — see ./shell3d), the active one
   *  included: a fitted-out storey is tens of thousands of meshes and the stack could not be drawn. */
  const [show3dShell, setShow3dShell] = useState(true);
  const [activeLevelId, setActiveLevelId] = useState<string | null>(null);
  const [levelSheets, setLevelSheets] = useState<Record<string, FloorPlanModel>>({});
  const levelStacksRef = useRef<Record<string, HistoryState<FloorPlanModel>>>({});
  const [levelSettingsOpen, setLevelSettingsOpen] = useState(false);
  /** A level's model completed to the editor's full shape. A sheet read from a file carries only what the
   *  file had; the active model is always `initialModel` + the file (see importPlanText), and a sheet swapped
   *  in must be the same, or code reading e.g. `constraints` / `graphAttrs` crashes on the switch. */
  const asSheet = (m: FloorPlanModel): FloorPlanModel => withLayerDefaults({ ...initialModel, ...m });
  /** The model as it is SAVED: the active level plus every other level packed in (a no-op for one level). */
  const packedForSave = (m: FloorPlanModel): FloorPlanModel => packLevels(m, activeLevelId, levelMeta, levelSheets);
  const [importDesignOpen, setImportDesignOpen] = useState(false);
  const [importImageOpen, setImportImageOpen] = useState(false);
  // Set Scale → By Area: state for the polygon-area calibration workflow.
  // We pin the room being calibrated when the dialog opens so subsequent
  // selection changes don't shift the reference area mid-edit.
  const [areaCalibrationDialogOpen, setAreaCalibrationDialogOpen] = useState(false);
  const [areaCalibrationInput, setAreaCalibrationInput] = useState("");
  const [areaCalibrationPickedRoomId, setAreaCalibrationPickedRoomId] = useState<string | null>(null);
  const [areaCalibrationCurrentAreaUnit, setAreaCalibrationCurrentAreaUnit] = useState(0);
  const [areaCalibrationCurrentAreaPx, setAreaCalibrationCurrentAreaPx] = useState(0);
  const [underlayCalibrationMode, setUnderlayCalibrationMode] = useState(false);
  const [isPanning, setIsPanning] = useState(false);
  /** True for the whole pan gesture (mousedown→mouseup); updated synchronously so drag/pan never races React state. */
  const viewportPanPointerActiveRef = useRef(false);
  const panLastScreen = useRef({ x: 0, y: 0 });
  /** Every pointer currently down, keyed by pointerId. Pointer events unify mouse / stylus / touch, so this
   *  one map is what lets the stage tell a two-finger viewport gesture from a one-contact draw, and what
   *  lets extra contacts (a palm landing mid-stroke) be ignored rather than hijacking the gesture. */
  const activePointersRef = useRef(new Map<number, { x: number; y: number }>());
  /** Live two-finger gesture — the pinch distance + centroid recorded on the previous move. */
  const pinchRef = useRef<{ dist: number; cx: number; cy: number } | null>(null);
  /** Preference: let a FINGER draw. Off (default) means touch only pans/zooms, which doubles as palm
   *  rejection — a resting palm reports pointerType "touch" and so can never start a stroke. Stylus ("pen")
   *  and mouse always draw. Turn on for a touchscreen with no stylus. */
  const [touchDraws, setTouchDraws] = useState<boolean>(false);
  const [spaceHeld, setSpaceHeld] = useState(false);
  const toolRef = useRef<Tool>(tool);
  const spaceHeldRef = useRef(false);
  toolRef.current = tool;
  spaceHeldRef.current = spaceHeld;
  const [isRightPanelCollapsed, setIsRightPanelCollapsed] = useState(false);
  /** Independent fold for the rightmost Tools column. Mirrors `propertiesPanelExpanded`
   *  for the Properties|Metrics sibling — toggled by a chevron on the canvas right
   *  edge. Independent so collapsing one doesn't affect the other. */
  const [toolsPanelExpandedColumn, setToolsPanelExpandedColumn] = useState<boolean>(true);
  /** Wall tool settings: floating overlay (does not expand the top toolbar). */
  const [wallOptionsOverlayOpen, setWallOptionsOverlayOpen] = useState(false);

  /** Outliner (Properties panel when nothing is selected): which group is expanded. */
  const [outlinerOpenGroup, setOutlinerOpenGroup] = useState<"nodes" | "edges" | "areas" | null>(null);

  /** Selected-wall properties: Inputs/Outputs foldables. */
  const [wallInputsExpanded, setWallInputsExpanded] = useState<boolean>(false);
  const [wallOutputsExpanded, setWallOutputsExpanded] = useState<boolean>(false);
  const [wallExtendExpanded, setWallExtendExpanded] = useState<boolean>(false);
  /** Global default from Default Settings: when true, show direction arrow on every wall. */
  const [globalShowDirection, setGlobalShowDirection] = useState<boolean>(false);
  /** Global default from Default Settings: when true, show the computed convergence/divergence level on every wall. */
  const [globalShowLevel, setGlobalShowLevel] = useState<boolean>(false);
  /** Active room-centroid drag: while set, the centroid Group's x/y stay pinned at the anchor so react-konva
   *  doesn't fight Konva's built-in drag positioning during history.replace re-renders. */
  const [centroidDragAnchor, setCentroidDragAnchor] = useState<{ roomId: string; x: number; y: number } | null>(null);

  /** Area Extend Behaviour — connection constraint for centroid drag:
   *  "with-walls" = translate polygon + incident walls together; "polygon-only" = move only the room polygon. */
  const [areaExtendExpanded, setAreaExtendExpanded] = useState<boolean>(false);
  const [areaConnectionConstraint, setAreaConnectionConstraint] = useState<"with-walls" | "polygon-only">("with-walls");
  const [areaDisplayExpanded, setAreaDisplayExpanded] = useState<boolean>(false);
  /** Region-semantics results cached per room id. Computed on demand via the Compute Semantics button. */
  const [regionSemanticsById, setRegionSemanticsById] = useState<Record<string, RegionSemantics>>({});
  const [areaSemanticsExpanded, setAreaSemanticsExpanded] = useState<boolean>(false);
  const [wallSplitExpanded, setWallSplitExpanded] = useState<boolean>(false);
  const [wallSplitCount, setWallSplitCount] = useState<number>(2);
  const [wallSplitType, setWallSplitType] = useState<"percent" | "length">("percent");
  const [wallSplitPercents, setWallSplitPercents] = useState<number[]>([50]);
  const [wallSplitLengths, setWallSplitLengths] = useState<number[]>([1]);
  /** Node panel Inputs/Outputs foldables. */
  const [nodeInputsExpanded, setNodeInputsExpanded] = useState<boolean>(false);
  /** Room properties Inputs foldable. */
  const [roomInputsExpanded, setRoomInputsExpanded] = useState<boolean>(true);
  /** Properties|Metrics tab in the room properties block — replaces the Inputs/Outputs
   *  foldable headers with a single mutually-exclusive tab strip. */
  const [roomPropsTab, setRoomPropsTab] = useState<"properties" | "metrics">("properties");
  /** Properties|Metrics tab in the wall (segment) properties block. */
  const [wallPropsTab, setWallPropsTab] = useState<"properties" | "metrics">("properties");
  /** Properties|Metrics tab in the node (point) properties block. */
  const [nodePropsTab, setNodePropsTab] = useState<"properties" | "metrics">("properties");
  /** Properties|Metrics tab for the NO-SELECTION panel, where the subject is the drawing as a whole:
   *  Properties shows the flow's Input Properties, Metrics its Output Metrics. Same pair the selected
   *  scopes use, so the panel reads the same way whether or not something is picked. */
  const [canvasPropsTab, setCanvasPropsTab] = useState<"properties" | "metrics">("properties");
  /** Selected NESTED component instance of a parametric attachment (SketchUp-style): the attachment id +
   *  the ref-instance path inside it. Drives the Components editor expansion + the canvas accent highlight.
   *  Attachment ids are globally unique (createId), so no host discriminator is needed. */
  const [selectedComponent, setSelectedComponent] = useState<{ attId: string; path: string } | null>(null);
  /** Properties|Metrics tab in the graph (Select → Graph scope) properties block. */
  const [graphPropsTab, setGraphPropsTab] = useState<"properties" | "metrics">("properties");
  /** Properties|Metrics tab in the underlay-image properties block. The image is a canvas component like
   *  any other as far as the Flow is concerned — its node feeds a brief and an Output Metrics node — so it
   *  gets the same tab strip as Space / Segment / Node rather than a bare pair of sliders. */
  const [imagePropsTab, setImagePropsTab] = useState<"properties" | "metrics">("properties");
  /** When true, the Properties and Metrics panes render side-by-side (and the panel auto-widens)
   *  instead of behind the Properties|Metrics tab strip. Toggled from the panel header. */
  const [propsSplitView, setPropsSplitView] = useState<boolean>(false);
  /** User-entered labels for selected graphs, keyed by their auto display id (GraphNNN). In-session. */
  const [graphLabels, setGraphLabels] = useState<Record<string, string>>({});
  /** Per-node metadata (label + type + column geometry), persisted in the model keyed by the
   *  node's stableKey so it survives the node moving, undo/redo, and export. Geometry in metres. */
  const updateNodeMeta = useCallback((stableKey: string, patch: Partial<NodeMeta>) => {
    const prev = history.state.nodeMeta ?? {};
    history.set({
      ...history.state,
      nodeMeta: { ...prev, [stableKey]: { ...prev[stableKey], ...patch } },
    });
  }, [history]);

  /** Add Furniture (Add Node ▸ Furniture). Does NOT create a canvas node — it authors the Flow graph,
   *  adding (or reusing) a Space node for the chosen space wired to a Place Object node carrying this
   *  furniture (see {@link syncObjectNodeToFlow}). The object then previews on the canvas via the flow and
   *  can be dragged along the boundary. A space selection is required. */
  const addFurnitureFromDraft = (d: FurnitureDraft) => {
    const sid = d.spaceId.trim();
    if (!sid) { toast.error("Select a space"); return; }
    const m = /(\d+)/.exec(sid);
    const room = m ? visibleRooms[parseInt(m[1], 10) - 1] : undefined;
    if (!room) { toast.error(`No space matches "${sid}"`); return; }
    syncObjectNodeToFlow(
      { type: "object", objectKind: d.kind, objWidth: d.width, objHeight: d.height, objOffsetBottom: d.offsetBottom, connectedSpaceId: sid, boundaryPosition: 50 },
      `furniture-${createId()}`,
      sid,
    );
    toast.success(`Added ${d.kind} to ${sid} in Flow`);
  };
  /** Create Grid (Add Node ▸ Grid): drop a parametric construction grid centred on the drawing (bbox
   *  centre of all walls, or the origin when empty). Stored in history.state.grids (undoable). */
  const addGridFromDraft = (d: GridDraft) => {
    const cellPx = Math.max(1, d.cellSize * pixelsPerMeter);
    const totalW = d.cols * cellPx, totalH = d.rows * cellPx;
    let cx = 0, cy = 0;
    const ws = history.state.walls;
    if (ws.length) {
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      for (const w of ws) for (const p of [w.start, w.end]) {
        minX = Math.min(minX, p.x); minY = Math.min(minY, p.y);
        maxX = Math.max(maxX, p.x); maxY = Math.max(maxY, p.y);
      }
      cx = (minX + maxX) / 2; cy = (minY + maxY) / 2;
    }
    const grid: import("./types").GridDef = {
      id: createId(),
      x: cx - totalW / 2,
      y: cy - totalH / 2,
      cols: d.cols, rows: d.rows, cellW: cellPx, cellH: cellPx,
      color: d.color,
    };
    history.set({ ...history.state, grids: [...(history.state.grids ?? []), grid] });
    toast.success(`Created ${d.cols}×${d.rows} grid`);
  };
  /** Patch the selected grid's definition (Properties edits). Undoable. */
  const updateSelectedGrid = useCallback((patch: Partial<import("./types").GridDef>) => {
    if (!selectedGridId) return;
    const h = historyRef.current;
    h.set({ ...h.state, grids: (h.state.grids ?? []).map((g) => (g.id === selectedGridId ? { ...g, ...patch } : g)) });
  }, [selectedGridId]);
  // Drop a stale grid selection if it was deleted / undone. (The mutual-exclusion effect lives after the
  // other selection states are declared.)
  useEffect(() => {
    if (selectedGridId && !(history.state.grids ?? []).some((g) => g.id === selectedGridId)) setSelectedGridId(null);
  }, [history.state.grids, selectedGridId]);
  /** Room properties Outputs foldable. */
  const [roomOutputsExpanded, setRoomOutputsExpanded] = useState<boolean>(true);
  const [nodeOutputsExpanded, setNodeOutputsExpanded] = useState<boolean>(false);
  // Auto-stamp layerId on any newly-created entity that's missing it. Acts as a
  // central catch-all so the 100+ history.set call sites don't all need to pass
  // layerId explicitly. Walls pick a default layer by segmentType (door→Door,
  // window→Window, anything else→Wall); other entity types fall back to the
  // active layer. Uses history.replace (no extra undo entry) and only fires
  // when at least one entity is missing the field, so the loop is self-limiting.
  useEffect(() => {
    const s = history.state;
    const missing = (arr: Array<{ layerId?: string }> | undefined) =>
      (arr ?? []).some((e) => !e.layerId);
    if (!missing(s.walls) && !missing(s.rooms) && !missing(s.objects) && !missing(s.furniture)) return;
    const layerIds = new Set((s.layers ?? []).map((l) => l.id));
    const wallDefault = layerIds.has("wall") ? "wall" : activeLayerId;
    const doorDefault = layerIds.has("door") ? "door" : wallDefault;
    const windowDefault = layerIds.has("window") ? "window" : wallDefault;
    const furnitureDefault = layerIds.has("furniture") ? "furniture" : activeLayerId;
    const stamp = <T extends { layerId?: string }>(arr: T[]): T[] =>
      arr.map((e) => (e.layerId ? e : { ...e, layerId: activeLayerId }));
    const stampWalls = (arr: Wall[]): Wall[] =>
      arr.map((w) => {
        if (w.layerId) return w;
        // Placement-along-boundary objects emit walls flagged isPlacementWall — route
        // those to the Furniture layer so they share the same visibility/lock as the
        // Add-Furniture sprites.
        if (w.isPlacementWall || w.isPlacementPreview) return { ...w, layerId: furnitureDefault };
        const seg = w.segmentType ?? "wall";
        // A layer whose id === the segment type (created when its Add Segment dropdown item was picked)
        // takes precedence, so custom seg-types (e.g. "staircase") land on their own layer.
        const lid = layerIds.has(seg) ? seg
          : seg === "door" ? doorDefault
          : seg === "window" ? windowDefault
          : wallDefault;
        return { ...w, layerId: lid };
      });
    const stampRooms = (arr: Room[]): Room[] =>
      arr.map((r) => {
        if (r.layerId) return r;
        // A layer whose id === the room type (created when its Add Space dropdown item was picked) wins.
        const rt = r.roomType;
        return { ...r, layerId: rt && layerIds.has(rt) ? rt : activeLayerId };
      });
    const stampFurniture = (arr: FurnitureItem[]): FurnitureItem[] =>
      arr.map((f) => {
        if (f.layerId) return f;
        const lid = layerIds.has(f.type) ? f.type : f.type === "door" ? doorDefault : f.type === "window" ? windowDefault : furnitureDefault;
        return { ...f, layerId: lid };
      });
    history.replace({
      ...s,
      walls: stampWalls(s.walls),
      rooms: stampRooms(s.rooms),
      objects: stamp(s.objects),
      furniture: stampFurniture(s.furniture),
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [history.state, activeLayerId]);

  /** Compute the layers array with a type layer (id === `slug`) ensured, WITHOUT committing history,
   *  and make it the active layer. Returns the (possibly extended) layers + the layer id. Agent/bridge
   *  handlers MUST fold the returned layers into the SAME history.set as the entity they create —
   *  calling {@link ensureLayerForType} and then history.set in one tick clobbers the layer, because
   *  both sets are built from the same stale render snapshot of history.state. */
  const ensureLayerInLayers = useCallback((layers: FloorPlanModel["layers"], slug: string, name?: string): { layers: NonNullable<FloorPlanModel["layers"]>; layerId: string; created: boolean } => {
    const list = layers ?? [];
    if (!slug) return { layers: list, layerId: activeLayerId, created: false };
    setActiveLayerId(slug);
    if (list.some((l) => l.id === slug)) return { layers: list, layerId: slug, created: false };
    const order = list.reduce((m, l) => Math.max(m, l.order), 0) + 1;
    const palette = ["#ef4444", "#f97316", "#eab308", "#22c55e", "#06b6d4", "#3b82f6", "#a855f7", "#ec4899"];
    const color = palette[list.length % palette.length];
    const label = name?.trim() || slug.split(/[-_\s]+/).filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
    return { layers: [...list, { id: slug, name: label, color, visible: true, locked: false, order }], layerId: slug, created: true };
  }, [activeLayerId]);

  /** Ensure a layer named for a drawing type exists (id === `slug`) and make it the active layer, so the
   *  next entity of that type auto-stamps onto it (see the layer-stamp effect above). Called when an Add
   *  Node / Add Segment / Add Space dropdown item is picked, so e.g. choosing "Wall" / "Door" / "Staircase"
   *  creates the matching layer (if absent) and draws into it. Returns the layer id. COMMITS a history
   *  step when it creates — don't follow it with another history.set in the same tick (see
   *  {@link ensureLayerInLayers}, which the agent draw/place handlers use instead). */
  const ensureLayerForType = useCallback((slug: string, name?: string) => {
    const r = ensureLayerInLayers(history.state.layers, slug, name);
    if (r.created) history.set({ ...history.state, layers: r.layers });
    return r.layerId;
  }, [ensureLayerInLayers, history]);

  useEffect(() => {
    const need = Math.max(1, Math.min(19, Math.round(wallSplitCount) - 1));
    setWallSplitPercents((arr) => {
      if (arr.length === need) return arr;
      const next = arr.slice(0, need);
      while (next.length < need) next.push(Math.max(1, Math.floor(100 / wallSplitCount)));
      return next;
    });
    setWallSplitLengths((arr) => {
      if (arr.length === need) return arr;
      const next = arr.slice(0, need);
      while (next.length < need) next.push(1);
      return next;
    });
  }, [wallSplitCount]);
  /** Direction constraint for wall handle drags: perpendicular = midpoint drag locks to normal,
   *  endpoint drag locks along wall axis; free = drag anywhere. */
  const [wallDirectionConstraint, setWallDirectionConstraint] = useState<"perpendicular" | "free">("free");

  /** Keep the new-wall draw mode in sync with View/Filling selection from Default Settings. */
  useEffect(() => {
    if (layerVisibility.viewGraph || layerVisibility.viewCurved) {
      setWallDrawMode("line");
      return;
    }
    // Sharp view — match existing view-mode popover mapping: Fill/Outline → "mitered", Union → "mitered-union".
    setWallDrawMode(layerVisibility.fillingUnion ? "mitered-union" : "mitered");
  }, [layerVisibility.viewSharp, layerVisibility.viewCurved, layerVisibility.viewGraph,
      layerVisibility.fillingFill, layerVisibility.fillingOutline, layerVisibility.fillingUnion]);
  const [shapesPopoverOpen, setShapesPopoverOpen] = useState(false);
  const stageRef = useRef<Konva.Stage | null>(null);
  const trRef = useRef<Konva.Transformer | null>(null);
  const jsonInputRef = useRef<HTMLInputElement | null>(null);
  const geojsonInputRef = useRef<HTMLInputElement | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);

  /** Public base URL of the shared Library (`<r2 public domain>/<prefix>`), or "" when the bucket is
   *  unconfigured. Written into an exported plan's `settings.library_path` so every relative reference
   *  in the file — the image underlay today, object paths next — has something to resolve against.
   *  Resolved once: the status call is cached in cloudLibrary and never changes during a session. */
  const [cloudLibraryBase, setCloudLibraryBase] = useState(libraryPath());
  /** Preferences ▸ Library Path, as typed. Committed to the shared setting on blur / Enter rather than
   *  per keystroke, so a half-typed URL never becomes the base every fetch resolves against. */
  const [libraryPathInput, setLibraryPathInput] = useState(libraryPath());
  const applyLibraryPath = useCallback((value: string) => {
    const next = value.trim().replace(/\/+$/, "");
    setLibraryPath(next);
    setLibraryPathInput(next);
    // Everything reads the setting on its next call; this state only drives what the UI SHOWS, and the
    // export's `library_path`, so it has to be re-derived here rather than left on the old value.
    void cloudLibraryBaseUrl().then(setCloudLibraryBase);
  }, []);
  /** The library base THIS PLAN's relative references resolve against — adopted from an imported file's
   *  `settings.library_path` and written straight back out on export, so a plan keeps naming the library
   *  it was authored against instead of being silently re-pointed at whatever this session happens to be
   *  configured for. Empty until a file that names one is imported; export then falls back to
   *  {@link cloudLibraryBase}. Object paths and the image underlay both resolve against it, so the two
   *  cannot disagree about where the plan's objects live. */
  const [planLibraryPath, setPlanLibraryPath] = useState("");
  useEffect(() => {
    let cancelled = false;
    // Resolves to the Preferences setting when one is configured (the normal case), else to the build's
    // own bucket — either way it is the SAME answer every fetch and every export uses.
    void cloudLibraryBaseUrl().then((base) => { if (!cancelled && base) setCloudLibraryBase(base); });
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    const src = history.state.imageUnderlay?.src;
    if (!src) {
      setImageElement(null);
      return;
    }
    let cancelled = false;
    const img = new window.Image();
    // A REMOTE underlay (an `https://` reference into the R2 Library, as opposed to an inlined data URL)
    // must be requested in CORS mode, for two independent reasons:
    //  • The dev server sends `Cross-Origin-Embedder-Policy: require-corp` (vite.config.ts — web-ifc's
    //    SharedArrayBuffer needs cross-origin isolation). Under require-corp a cross-origin subresource
    //    is BLOCKED unless it carries `Cross-Origin-Resource-Policy` or is fetched with CORS. The r2.dev
    //    public domain sends no CORP header, so a plain <img> never loads and the canvas shows nothing.
    //  • Even where it did load, a no-CORS image TAINTS the Konva stage, and Export PNG (stage.toDataURL)
    //    then throws. osmMap.ts sets this on tile loads for the same second reason.
    // Must be assigned BEFORE `src` or it has no effect. Skipped for data URLs, which are not a fetch at
    // all — and for which a crossOrigin attribute would be meaningless.
    if (!src.startsWith("data:")) img.crossOrigin = "anonymous";
    img.onload = () => {
      if (!cancelled) {
        setImageElement(img);
      }
    };
    img.onerror = () => {
      if (!cancelled) {
        setImageElement(null);
      }
    };
    img.src = src;
    return () => {
      cancelled = true;
    };
  }, [history.state.imageUnderlay?.src]);

  /** Loaded <img> per OVERLAY src, keyed by src so an overlay that is only re-positioned or faded does
   *  not re-decode. Same CORS reasoning as the base underlay above: a remote src must be requested in
   *  CORS mode or it is blocked by require-corp and taints the stage. Entries for srcs no longer in the
   *  state are dropped, which is what releases the decoded bitmap when an overlay is removed. */
  const [overlayElements, setOverlayElements] = useState<Record<string, HTMLImageElement>>({});
  const overlaySrcKey = (history.state.imageOverlays ?? []).map((o) => o.src).join("\0");
  useEffect(() => {
    const srcs = (historyRef.current.state.imageOverlays ?? []).map((o) => o.src).filter(Boolean);
    const wanted = new Set(srcs);
    setOverlayElements((prev) => {
      const kept = Object.fromEntries(Object.entries(prev).filter(([s]) => wanted.has(s)));
      return Object.keys(kept).length === Object.keys(prev).length ? prev : kept;
    });
    let cancelled = false;
    for (const src of wanted) {
      setOverlayElements((prev) => {
        if (prev[src]) return prev; // already decoded
        const img = new window.Image();
        if (!src.startsWith("data:")) img.crossOrigin = "anonymous";
        img.onload = () => { if (!cancelled) setOverlayElements((p) => ({ ...p, [src]: img })); };
        img.src = src;
        return prev;
      });
    }
    return () => { cancelled = true; };
  }, [overlaySrcKey]);

  /** Put a generated picture on the canvas as a new OVERLAY, REGISTERED on the picture it was made from.
   *
   *  Registration is the feature. A render dropped at the origin, or scaled to some default width, can
   *  only be looked at; laid on the source's exact box it can be COMPARED — fade it down and the walls
   *  it moved, the openings it invented and the text it dropped separate themselves from the original
   *  without measuring anything. `sourceSrc` is the data URL that was actually sent to the model, which
   *  is how the box is found: it matches an existing overlay (a render of a render), or the base
   *  underlay, or nothing — a Snapshot of drawn geometry rather than an imported picture — in which case
   *  the base underlay's box is still the honest frame, since that is what the snapshot was of.
   *
   *  Starts at 0.6 opacity rather than 1: landing fully opaque hides the plan underneath it, which looks
   *  like the import replaced the drawing rather than stacked on it. */
  const addImageOverlay = useCallback((dataUrl: string, sourceSrc?: string) => {
    if (!dataUrl.startsWith("data:")) return;
    const s0 = historyRef.current.state;
    const from = (sourceSrc && (s0.imageOverlays ?? []).find((o) => o.src === sourceSrc)) || s0.imageUnderlay;
    // MEASURE the result before placing it. This used to copy the source's `width`/`height` straight
    // across without ever loading the picture, which registered perfectly by construction — and lied:
    // a 1024-px render forced into a 240-px box is a STRETCH, and a stacked import of the same two files
    // on a fresh canvas then landed somewhere else entirely, because that path measures honestly. One
    // rule for both now, in fitOntoBox.
    const img = new window.Image();
    img.onload = () => {
      const h = historyRef.current;
      const s = h.state;
      const existing = s.imageOverlays ?? [];
      const natW = img.naturalWidth || img.width;
      const natH = img.naturalHeight || img.height;
      // No picture on the canvas at all — nothing to register against, so fall back to a placement at
      // the origin rather than a 1-pixel-per-unit box no one can see.
      const box = from
        ? fitOntoBox(natW, natH, from)
        : { x: -natW / 2, y: -natH / 2, width: natW, height: natH, scale: 1 };
      let n = existing.length + 1;
      while (existing.some((o) => o.id === `render-${n}`)) n++;
      h.set({
        ...s,
        imageOverlays: [...existing, {
          id: `render-${n}`, src: dataUrl, ...box,
          opacity: 0.6, locked: true, layerId: DEFAULT_IMAGE_LAYER_ID,
        }],
      });
      toast.success(`Added render-${n} to the canvas`);
    };
    img.src = dataUrl;
  }, []);

  const [autoGenDialogOpen, setAutoGenDialogOpen] = useState(false);
  const [autoGenConfigJson, setAutoGenConfigJson] = useState(() => JSON.stringify(DEFAULT_GENERATE_CONFIG, null, 2));
  const [autoGenError, setAutoGenError] = useState<string | null>(null);
  const autoGenJsonInputRef = useRef<HTMLInputElement | null>(null);

  /** Stored generation state for interactive room dragging (non-null when auto-generated layout is active). */
  const [generatedLayout, setGeneratedLayout] = useState<GeneratedLayoutState | null>(null);
  /** Per-floorplate layouts — keyed by floorplate-boundary room id. Enables multiple simultaneous floorplates. */
  const [floorplateLayouts, setFloorplateLayouts] = useState<Record<string, GeneratedLayoutState>>({});
  /** Currently active floorplate room id — determines which floorplate "+ Room" adds to. */
  const [activeFloorplateId, setActiveFloorplateId] = useState<string | null>(null);
  /** Keep a ref so drag callbacks always see the latest layout without stale closures. */
  const historyRef = useRef(history);
  historyRef.current = history;
  const generatedLayoutRef = useRef<GeneratedLayoutState | null>(null);
  generatedLayoutRef.current = generatedLayout;
  /** Room currently being dragged (label) — null when not dragging. */
  const [draggingRoom, setDraggingRoom] = useState<string | null>(null);

  /** Splitting Actions state for Room-type properties panel. */
  const [splitCount, setSplitCount] = useState<number>(2);
  const [splitAngle, setSplitAngle] = useState<number>(0);
  const [splitMode, setSplitMode] = useState<"equal" | "ratio" | "target" | "length">("equal");
  const [splitRatios, setSplitRatios] = useState<number[]>([50, 50]);
  const [splitTarget, setSplitTarget] = useState<number>(15);
  /** Edge-based length splitting. splitEdge = index of the reference edge (null = manual angle). */
  const [splitEdge, setSplitEdge] = useState<number | null>(null);
  const [splitEdgeFlip, setSplitEdgeFlip] = useState<boolean>(false);
  /** Flow editor (node-graph pipeline) overlay open state. */
  const [flowOpen, setFlowOpen] = useState<boolean>(false);
  /** Flow editor minimized (collapsed to a bar — engine keeps running, canvas reclaims the area). */
  const [flowMinimized, setFlowMinimized] = useState<boolean>(false);
  /** Imperative handle to the flow Panel, for the minimize / maximize / restore window controls. */
  const flowPanelRef = useRef<ImperativePanelHandle>(null);
  /** Pure-evaluated Flow pipeline output polygons, rendered as a canvas overlay (preview). */
  const [flowPreview, setFlowPreview] = useState<FlowPreviewItem[]>([]);
  /** Ref mirror of the OVERLAY's live preview — the agent's flow_apply reads it (after the eval settles)
   *  to summarise what each node produced without racing React state. */
  const flowPreviewRef = useRef<FlowPreviewItem[]>([]);
  // Keep the ref in step with the state on EVERY render (the overlay's onPreview also sets it synchronously;
  // this additionally covers the closed-overlay headless path, which only calls setFlowPreview) so a
  // Properties-tab Agent run reads the current preview without racing React state.
  flowPreviewRef.current = flowPreview;
  /** Flow "Live" mode (pilot) — when on, supported nodes (currently Inset) materialise their output as
   *  REAL wall segments (→ auto-detected Space) that regenerate on every parameter change, instead of a
   *  preview overlay you must Run to commit. See the live-materialise effect below. */
  const [liveFlow, setLiveFlow] = useState(false);
  /** Node ids whose output is currently materialised by Live mode — their preview overlay is suppressed
   *  (the real geometry stands in for it), read during the canvas overlay render. */
  const liveOwnedNodeIdsRef = useRef<Set<string>>(new Set());
  /** Attachment ids of host-aware pipeline objects (Site/Floor/Massing) whose pipeline steps are currently
   *  materialised as real Spaces by Live mode — their display-only overlay is suppressed (the committed
   *  per-op Spaces stand in for it), read during the canvas attachment overlay render. */
  const liveOwnedAttIdsRef = useRef<Set<string>>(new Set());
  /** Display ids (e.g. "Space001") of Space nodes whose eye is toggled off in the Flow editor — those
   *  spaces are hidden on the canvas while the editor drives the view. */
  const [hiddenFlowSpaceIds, setHiddenFlowSpaceIds] = useState<string[]>([]);
  /** Actual room ids to hide on the canvas, resolved from the Flow editor's hidden Space display ids
   *  (SpaceNNN = visibleRooms[NNN-1]). Only active while the Flow editor is open. */
  const hiddenFlowRoomIds = useMemo(() => {
    const s = new Set<string>();
    if (!flowOpen || hiddenFlowSpaceIds.length === 0) return s;
    for (const disp of hiddenFlowSpaceIds) {
      const m = /^Space(\d+)$/.exec(disp.trim());
      if (!m) continue;
      const room = visibleRooms[parseInt(m[1], 10) - 1];
      if (room) s.add(room.id);
    }
    return s;
  }, [flowOpen, hiddenFlowSpaceIds, visibleRooms]);
  /** Colour filters ("*" = every stroke) from Freehand-source nodes whose eye is toggled off in the Flow
   *  editor — the matching canvas freehand strokes are hidden while the editor drives the view. */
  const [hiddenFreehandColors, setHiddenFreehandColors] = useState<string[]>([]);
  /** True when a committed freehand stroke (its kind/stroke colour) is hidden by a Freehand-source eye toggle.
   *  Case-insensitive colour match; "*" hides every stroke. Only active while the Flow editor is open. */
  const isFreehandHiddenByFlow = useCallback((kind: string, stroke: string | undefined): boolean => {
    if (kind !== "freehand" || !flowOpen || hiddenFreehandColors.length === 0) return false;
    return hiddenFreehandColors.includes("*") || hiddenFreehandColors.includes((stroke ?? "").trim().toLowerCase());
  }, [flowOpen, hiddenFreehandColors]);
  /** Display ids ("GridNNN") of Grid-source nodes whose eye is toggled off in the Flow editor. */
  const [hiddenFlowGridIds, setHiddenFlowGridIds] = useState<string[]>([]);
  /** Actual grid ids to hide on the canvas, resolved from the Flow editor's hidden Grid display ids
   *  (GridNNN = grids[NNN-1], or a direct id match). Only active while the Flow editor is open. */
  const hiddenFlowGridIdSet = useMemo(() => {
    const s = new Set<string>();
    if (!flowOpen || hiddenFlowGridIds.length === 0) return s;
    for (const disp of hiddenFlowGridIds) {
      const m = /^Grid(\d+)$/.exec(disp.trim());
      const g = m ? (history.state.grids ?? [])[parseInt(m[1], 10) - 1] : (history.state.grids ?? []).find((x) => x.id === disp.trim());
      if (g) s.add(g.id);
    }
    return s;
  }, [flowOpen, hiddenFlowGridIds, history.state.grids]);
  /** Whether the image underlay is the current selection (via the "Image" select scope). Drives the
   *  Properties panel (Scale / Opacity) and the on-canvas selection highlight. */
  const [imageSelected, setImageSelected] = useState<boolean>(false);
  /** WHICH picture is selected: "" for the base underlay, or an overlay's id ("render-1"). Meaningful
   *  only while `imageSelected` is true. Two pieces of state rather than one nullable id because "" is a
   *  REAL value here — the base underlay carries no id — so a single `string | null` would have to mean
   *  both "the base image" and "nothing selected", and every reader would need to know which.
   *  This is what an Image node's Grab from selection follows. */
  const [selectedImageId, setSelectedImageId] = useState<string>("");
  /** The imported underlay image as an RGBA buffer + its world box, for the Flow Image / Vectorisation
   *  nodes AND for an image-hosted object's payload. Extracted only while the Flow editor is open or a
   *  picture is selected (getImageData is heavy); re-extracts when the image or its placement changes. */
  const flowImageData = useMemo(() => {
    const underlay = history.state.imageUnderlay;
    if ((!flowOpen && !imageSelected) || !underlay || !imageElement) return undefined;
    const w = imageElement.naturalWidth || imageElement.width;
    const h = imageElement.naturalHeight || imageElement.height;
    if (!w || !h) return undefined;
    const canvas = document.createElement("canvas");
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;
    try {
      ctx.drawImage(imageElement, 0, 0, w, h);
      const data = ctx.getImageData(0, 0, w, h).data;
      return { data, w, h, box: { x: underlay.x, y: underlay.y, scale: underlay.scale || 1 }, key: underlay.src };
    } catch { return undefined; }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flowOpen, imageSelected, imageElement, history.state.imageUnderlay?.src, history.state.imageUnderlay?.x, history.state.imageUnderlay?.y, history.state.imageUnderlay?.scale]);
  /** The same RGBA extraction for every OVERLAY, keyed by its id — what an Image node's `id` field
   *  selects. Without this the flow could only ever read the base drawing, so a render laid over the
   *  plan could be looked at but not traced, which is half a feature: the reason to generate a clean
   *  line drawing is to vectorise THAT rather than the furniture-laden original.
   *  Only extracted while the Flow editor is open, for the same reason the base one is — getImageData
   *  over a full-resolution picture is not something to do on every unrelated render. */
  const flowOverlayImages = useMemo(() => {
    const out: Record<string, { data: Uint8ClampedArray; w: number; h: number; box: { x: number; y: number; scale: number }; key: string }> = {};
    if (!flowOpen && !imageSelected) return out;
    for (const ov of history.state.imageOverlays ?? []) {
      const el = ov.id ? overlayElements[ov.src] : undefined;
      if (!el) continue;
      const w = el.naturalWidth || el.width;
      const h = el.naturalHeight || el.height;
      if (!w || !h) continue;
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext("2d");
      if (!ctx) continue;
      try {
        ctx.drawImage(el, 0, 0, w, h);
        out[ov.id!] = { data: ctx.getImageData(0, 0, w, h).data, w, h, box: { x: ov.x, y: ov.y, scale: ov.scale }, key: ov.src };
      } catch { /* tainted canvas — that overlay is simply not readable by the flow */ }
    }
    return out;
  }, [flowOpen, overlayElements, history.state.imageOverlays]);
  /** A 2D context over the underlay image, cached so "Grab Colour" reads ONE pixel per click instead of
   *  re-rasterising the whole picture each time. `willReadFrequently` is set because that is exactly what
   *  this does. Rebuilt only when the image element or its size changes. */
  const pickCanvasRef = useRef<{ el: HTMLImageElement; ctx: CanvasRenderingContext2D; w: number; h: number } | null>(null);
  /** Read the underlay's pixel under a WORLD point. The underlay is drawn at (u.x, u.y) scaled by
   *  u.scale, so the inverse of that placement is the whole mapping — the same one Vectorisation uses to
   *  put traced pixels back on canvas, run backwards. Returns null when there is no image, when the point
   *  is outside it, or when the canvas is tainted (a cross-origin source), which is a real possibility
   *  and reads as "cannot sample" rather than as a crash. */
  const sampleUnderlayColor = useCallback((world: Point): { r: number; g: number; b: number; hex: string; ix: number; iy: number } | null => {
    const u = history.state.imageUnderlay;
    if (!u?.src || !imageElement) return null;
    const w = imageElement.naturalWidth || imageElement.width;
    const h = imageElement.naturalHeight || imageElement.height;
    if (!w || !h) return null;
    let cache = pickCanvasRef.current;
    if (!cache || cache.el !== imageElement || cache.w !== w || cache.h !== h) {
      const canvas = document.createElement("canvas");
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (!ctx) return null;
      try { ctx.drawImage(imageElement, 0, 0, w, h); } catch { return null; }
      cache = { el: imageElement, ctx, w, h };
      pickCanvasRef.current = cache;
    }
    const sc = u.scale || 1;
    const ix = Math.floor((world.x - u.x) / sc);
    const iy = Math.floor((world.y - u.y) / sc);
    if (ix < 0 || iy < 0 || ix >= w || iy >= h) return null;
    let d: Uint8ClampedArray;
    try { d = cache.ctx.getImageData(ix, iy, 1, 1).data; } catch { return null; }
    const [r, g, b] = [d[0], d[1], d[2]];
    const hex = `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`.toUpperCase();
    return { r, g, b, hex, ix, iy };
  }, [history.state.imageUnderlay, imageElement]);

  /** OSM basemap clipped to the site region, stitched into a texture for the 3D ground plane (the real
   *  map under the building, with the site centred). Recomputed (debounced) when the site / map changes. */
  const [osmGround, setOsmGround] = useState<{ src: string; x: number; y: number; w: number; h: number; scale: number } | null>(null);
  /** Site is ~20% of the visible map area (region area = site area / SITE_AREA_FRACTION). */
  const SITE_AREA_FRACTION = 0.2;
  /** Live massing previews (Flow "Massing" nodes) → extruded as buildings in the 3D view. Driven by the
   *  Flow editor while open, and by the Space-attached flow (Properties-tab params) while closed, so an
   *  Optimise Rectangle → Massing chain shows n floors before committing. */
  const flowMassingPreview = useMemo(() => {
    const m = flowPreview.map((i) => i.massing).filter((x): x is NonNullable<FlowPreviewItem["massing"]> => !!x);
    return m.length ? m : undefined;
  }, [flowPreview]);
  // Flow "Mesh to 3D" output — every terminal's meshes flattened for the 3D canvas to render.
  const flowMeshPreview = useMemo(() => {
    const m = flowPreview.flatMap((i) => i.meshes ?? []);
    return m.length ? m : undefined;
  }, [flowPreview]);
  // Parametric objects attached to NODES that carry their own geometry → 3D meshes (footprints extruded by
  // height), shown in the 3D view via the same Mesh-to-3D path as the Flow editor. Anchored at each node,
  // with the instance's edited params overriding the file defaults.
  const parametricObjectMeshes = useMemo<HostedFlowMesh[]>(() => {
    if (!is3dOpen) return [];
    const lib = history.state.objectLibrary ?? {};
    const meta = history.state.nodeMeta ?? {};
    const out: HostedFlowMesh[] = [];
    for (const node of wallNodes) {
      for (const att of meta[node.stableKey]?.attachments ?? []) {
        const obj = lib[att.objectId];
        if (!objHasGeometry(obj)) continue;
        // A spine places itself from the host points, so a NODE host is the anchor itself: (0,0) local.
        const prisms = evalParametricPrisms(objText(obj), { x: node.x, y: node.y }, pixelsPerMeter, vp(att.params), objIsSpine(obj) ? [{ x: 0, y: 0 }] : undefined, resolveObjectDef, att.childParams);
        if (prisms.length) out.push({ id: `pobj-${node.stableKey}-${att.id}`, prisms, host: { kind: "node", id: node.stableKey, attId: att.id }, bind: bindOf(att, lib[att.objectId]) });
      }
    }
    return out;
  }, [wallNodes, history.state.nodeMeta, history.state.objectLibrary, pixelsPerMeter, is3dOpen, uiRenderMode]);
  // Floor slabs (attached to a Space) + Wall bands (attached to a Segment) → 3D meshes. Each takes its
  // footprint from the HOST — a floor uses the room polygon, a wall uses the segment band at its canvas
  // thickness — and extrudes by the object's param: a floor by `thickness` below `level`, a wall by `height`
  // above `base`. Footprints are plan-px world coords; yTop/yBottom are metres (same convention as above).
  // Largest inscribed rectangle per Space that has attached objects. A non-host-aware object (e.g. a
  // staircase) is placed INSIDE this rectangle at ITS orientation — so attaching a staircase to a Space
  // fits it to the usable rectangle (like a staircase on a segment fits the segment length), instead of the
  // axis-aligned room bbox. Keyed by room id; consumed by both the 3D prism render (below) and the 2D
  // overlay. Recomputed only when the room set/geometry changes (attachment-only rooms).
  const roomInscribedRects = useMemo(() => {
    const m = new Map<string, { cx: number; cy: number; angleRad: number; wPx: number; hPx: number }>();
    const seen = new Set<string>();
    const consider = (room: Room) => {
      if (seen.has(room.id) || !(room.attachments?.length) || room.points.length < 3) return;
      seen.add(room.id);
      // Only a FULL object is fitted into the rectangle. Basic draws the host outline and Nothing draws
      // nothing, so a space whose objects are all Basic/Nothing skips the search — it costs ~0.1 s per space
      // and far more on a long polygon, which is what froze a 400-space master plan for a minute.
      if (room.attachments.every((a) => renderModeOf(vp(a.params)) !== "Full")) return;
      const r = largestInscribedRectangle(room.points);
      if (!r || r.corners.length < 4) return;
      const [c0, c1, c2] = r.corners;
      m.set(room.id, {
        cx: (c0.x + c2.x) / 2, cy: (c0.y + c2.y) / 2,
        angleRad: Math.atan2(c1.y - c0.y, c1.x - c0.x),
        wPx: Math.max(1e-6, Math.hypot(c1.x - c0.x, c1.y - c0.y)),
        hPx: Math.max(1e-6, Math.hypot(c2.x - c1.x, c2.y - c1.y)),
      });
    };
    for (const room of history.state.rooms) consider(room);
    for (const room of visibleRooms) consider(room);
    return m;
  }, [history.state.rooms, visibleRooms, uiRenderMode]);

  /** Space-floor + segment wall/door/window meshes for ONE sheet. The active level calls it through the memo
   *  below; the other levels call it for the "All" 3D stack (without column carves or inscribed-rect fitting
   *  inputs from the active sheet — those are recomputed or skipped per sheet). */
  const buildFloorWallMeshes = (
    sheet: { rooms: Room[]; walls: FloorPlanModel["walls"]; objectLibrary?: FloorPlanModel["objectLibrary"] },
    miteredPolygons: Map<string, Point[]>,
    roomInscribedRects: Map<string, { cx: number; cy: number; angleRad: number; wPx: number; hPx: number }>,
    wallCarveFootprints: Point[][],
  ): HostedFlowMesh[] => {
    const lib = sheet.objectLibrary ?? {};
    const out: HostedFlowMesh[] = [];
    // Traced plans often have OVERLAPPING rooms (a hall lapping a toilet, two bedrooms sharing a band). Their floor
    // plates sit in one plane and, wearing different finishes, flicker. The smaller room's finish reads on top (a
    // bathroom tile laps the hall boards): lift each plate by a sub-millimetre step ranked by area, smallest highest.
    const roomArea = (pts: Point[]) => Math.abs(pts.reduce((a, p, i) => { const q = pts[(i + 1) % pts.length]; return a + p.x * q.y - q.x * p.y; }, 0)) / 2;
    const floorLift = new Map(
      [...sheet.rooms].sort((a, b) => roomArea(b.points) - roomArea(a.points) || a.id.localeCompare(b.id)).map((r, i) => [r.id, (i + 1) * 0.0015]),
    );
    const pnum = (att: SegmentAttachment, k: string, d: number): number => { const v = att.params[k]; const x = typeof v === "number" ? v : Number(v); return isFinite(x) ? x : d; };
    const pcol = (att: SegmentAttachment, d: string): string => (typeof att.params.color === "string" && att.params.color ? att.params.color : d);
    for (const room of sheet.rooms) {
      if (room.points.length < 3) continue;
      // Host footprint → local-metre coords centred on the room centroid; the engine's `placer(anchor, ppm)`
      // reconstructs world pixels. Any space-attached parametric object with a `geometry` block extrudes its
      // OWN 3D from these params + the host polygon (Floor = one slab, Massing = a stacked/tapered tower) —
      // one generic path, no per-object code.
      const c = polygonCentroid(room.points);
      const hostLocal = room.points.map((p) => ({ x: (p.x - c.x) / pixelsPerMeter, y: (p.y - c.y) / pixelsPerMeter }));
      for (const att of room.attachments ?? []) {
        const obj = lib[att.objectId];
        if (!objHasGeometry(obj)) continue;
        const defText = objText(obj);
        let prisms = evalParametricPrisms(defText, c, pixelsPerMeter, vp(att.params), hostLocal, resolveObjectDef, att.childParams);
        // Generic FIT-TO-SPACE (mirrors the 2D overlay): a non-host-aware object is fitted INSIDE the Space's
        // largest inscribed rectangle at that rectangle's orientation (falling back to the room bbox); heights
        // stay true. Host-aware objects extrude as-authored.
        if (prisms.length && !pobjIsHostAware(defText)) {
          const gb = polysBBox(prisms.flatMap((p) => [p.bottom, p.top]));
          const rect = roomInscribedRects.get(room.id);
          if (gb && rect) {
            const tp = fitObjectToInscribedRect(rect, gb);
            prisms = prisms.map((p) => ({ ...p, bottom: p.bottom.map(tp), top: p.top.map(tp) }));
          } else if (gb) {
            const rb = polysBBox([room.points]);
            if (rb) {
              const s = Math.min((rb.maxX - rb.minX) / Math.max(1e-6, gb.maxX - gb.minX), (rb.maxY - rb.minY) / Math.max(1e-6, gb.maxY - gb.minY));
              const gcx = (gb.minX + gb.maxX) / 2, gcy = (gb.minY + gb.maxY) / 2;
              const rcx = (rb.minX + rb.maxX) / 2, rcy = (rb.minY + rb.maxY) / 2;
              const tp = (p: Point): Point => ({ x: rcx + (p.x - gcx) * s, y: rcy + (p.y - gcy) * s });
              prisms = prisms.map((p) => ({ ...p, bottom: p.bottom.map(tp), top: p.top.map(tp) }));
            }
          }
        }
        const lift = floorLift.get(room.id) ?? 0;
        if (lift) prisms = prisms.map((p) => ({ ...p, yBottom: p.yBottom + lift, yTop: p.yTop + lift }));
        if (prisms.length) out.push({ id: `pobj-space-${room.id}-${att.id}`, prisms, host: { kind: "space", id: room.id, attId: att.id }, bind: roomFloorBind(att, lib[att.objectId], room) });
      }
    }
    for (const w of sheet.walls) {
      // The 3D canvas suppresses its own extrusion for a segment hosting a Wall object because THIS band is
      // its 3D — so a hidden layer has to be honoured here too, or hiding the layer would leave the band
      // behind as the only thing still drawn.
      if (!isEntityVisible(w)) continue;
      const atts = w.attachments ?? [];
      // A WALL object hands its 3D to the canvas whether it is a spine or a rules object — it names the band's
      // base and height, and the canvas owns the MITRED footprint, which is the only thing that makes corners
      // join. Testing `!objIsSpine` here meant an imported spine Wall (wall.json) matched nothing: its own
      // Render 3D row is deliberately off, so the canvas skipped it and the object drew nothing either, and a
      // segment drawn with Add Segment → Wall (committed as `segmentType: "line"`, so the 3D canvas's own
      // extrusion doesn't fire) had no 3D at all. `symbol === "wall"` is the same test the opening tool
      // (openingSpanOnWall) and the 2D line-mode branch already use.
      const wallAtt = atts.find((a) => lib[a.objectId]?.meta.symbol === "wall");
      // Same for the opening that carves the band into spandrels: door.json / window.json ARE spines, so a
      // spine-blind test never matched one — now that a spine Wall gets its band, a door on the same segment
      // would otherwise be buried in solid wall.
      const openAtt = atts.find((a) => { const s = lib[a.objectId]?.meta.symbol; return s === "door" || s === "window"; });
      // GENERIC parametric objects on a segment (staircase, furniture, …) — everything with a geometry
      // block that isn't the wall band or a door/window opening; host-aligned below like the 2D branch.
      const genericAtts = atts.filter((a) => { const o = lib[a.objectId]; const s = o?.meta.symbol;
        // The band above IS the wall — never draw the object's own copy of it on top of the canvas one.
        if (s === "wall") return false;
        // A spine always draws its own solids — `symbol` on one names a menu glyph, not a placeholder.
        return objIsSpine(o) || (objHasGeometry(o) && s !== "door" && s !== "window"); });
      if (!wallAtt && !openAtt && genericAtts.length === 0) continue;
      const dx = w.end.x - w.start.x, dy = w.end.y - w.start.y, L = Math.hypot(dx, dy);
      if (L < 1e-6) continue;
      // Extrude the MITERED footprint (same polygon the 2D plan uses) so corners join cleanly in 3D
      // instead of overlapping per-segment rectangles. Convex-hull it first: the miter polygon carries
      // collinear centerline midpoints (and can be concave at T/X junctions), but the prism caps are
      // fan-triangulated (convex-only) — the hull keeps the L-corner/loop shape while guaranteeing convex.
      const nx = -dy / L, ny = dx / L, ht = Math.max(1, (w.thickness ?? 10) / 2);
      const mitre = miteredPolygons.get(w.id);
      const hull = mitre && mitre.length >= 3 ? computeConvexHull(mitre) : [];
      const foot = hull.length >= 3
        ? hull
        : [
            { x: w.start.x + nx * ht, y: w.start.y + ny * ht },
            { x: w.end.x + nx * ht, y: w.end.y + ny * ht },
            { x: w.end.x - nx * ht, y: w.end.y - ny * ht },
            { x: w.start.x - nx * ht, y: w.start.y - ny * ht },
          ];
      const wbase = wallAtt ? pnum(wallAtt, "base", 0) : 0;
      // Wall band — full height, OR carved into spandrels around an opening so the door/window sits in real
      // wall (band over the head, and under the sill for a window). Door 0→Height, window Sill→Lintel.
      if (wallAtt) {
        const wtop = wbase + Math.max(0.05, pnum(wallAtt, "height", 2.7));
        const wcol = pcol(wallAtt, "#94a3b8");
        // Wall boolean: subtract the carve footprints (columns, …) that overlap this wall's band, so the
        // parametric wall prism has the column punched through (Shape-with-holes extrusion). Cheap bbox
        // pre-check; no carve → the plain single-piece band, exactly as before.
        const fb = polysBBox([foot]);
        const hits = fb ? wallCarveFootprints.filter((cp) => { const cb = polysBBox([cp]); return !!cb && cb.minX <= fb.maxX && cb.maxX >= fb.minX && cb.minY <= fb.maxY && cb.maxY >= fb.minY; }) : [];
        const pieces = hits.length ? subtractPolygon(foot, hits) : [{ outer: foot, holes: [] as Point[][] }];
        const bandPrisms = (y0: number, y1: number) => pieces
          .filter((p) => p.outer.length >= 3)
          .map((p) => ({ bottom: p.outer, top: p.outer, yBottom: y0, yTop: y1, color: wcol, ...(p.holes.length ? { holes: p.holes } : {}) }));
        if (openAtt) {
          const isWin = lib[openAtt.objectId]?.meta.symbol === "window";
          // A spine door names its head `lintelHeight` (a rules door used `height`) — read both, or a spine
          // door would carve its spandrel at the 2.1 m fallback instead of at its own head.
          const lintel = wbase + (isWin ? pnum(openAtt, "lintelHeight", 2.1) : pnum(openAtt, "lintelHeight", pnum(openAtt, "height", 2.1)));
          const sillTop = wbase + (isWin ? pnum(openAtt, "sillHeight", 0.9) : 0);
          if (sillTop > wbase + 0.01) out.push({ id: `wall-${w.id}-sill`, prisms: bandPrisms(wbase, Math.min(sillTop, wtop)), host: { kind: "segment", id: w.id, attId: wallAtt.id }, bind: bindOf(wallAtt, lib[wallAtt.objectId]) });
          if (lintel < wtop - 0.01) out.push({ id: `wall-${w.id}-head`, prisms: bandPrisms(Math.max(lintel, wbase), wtop), host: { kind: "segment", id: w.id, attId: wallAtt.id }, bind: bindOf(wallAtt, lib[wallAtt.objectId]) });
        } else {
          out.push({ id: `wall-${w.id}-${wallAtt.id}`, prisms: bandPrisms(wbase, wtop), host: { kind: "segment", id: w.id, attId: wallAtt.id }, bind: bindOf(wallAtt, lib[wallAtt.objectId]) });
        }
      }
      // Door / Window → its OWN parametric 3D geometry (the .pobj.json geometry block), oriented along the
      // wall at the opening centre. The geometry encodes the vertical levels; lift it by the wall base.
      if (openAtt) {
        const oObj = lib[openAtt.objectId];
        // A SPINE door / window builds its own solids through the generic branch below (its Render 3D rows are
        // on) — placing it here as well would draw the leaf and frame twice.
        if (!objIsSpine(oObj) && objHasGeometry(oObj)) {
          const cx = (w.start.x + w.end.x) / 2, cy = (w.start.y + w.end.y) / 2;
          const angle = (Math.atan2(dy, dx) * 180) / Math.PI;
          const prisms = evalParametricPrisms(objText(oObj), { x: cx, y: cy }, pixelsPerMeter, vp({ ...openAtt.params, rotation: angle }), undefined, resolveObjectDef, openAtt.childParams);
          const lifted = wbase ? prisms.map((p) => ({ ...p, yBottom: p.yBottom + wbase, yTop: p.yTop + wbase })) : prisms;
          if (lifted.length) out.push({ id: `opening-${w.id}-${openAtt.id}`, prisms: lifted, host: { kind: "segment", id: w.id, attId: openAtt.id }, bind: bindOf(openAtt, lib[openAtt.objectId]) });
        }
      }
      // Generic objects → evaluate un-rotated at the segment midpoint, then HOST-ALIGN in plan (mirrors
      // the 2D branch): X extent stretched to the segment length, depth centred on the line, rotated with
      // the segment. Heights stay true.
      for (const att of genericAtts) {
        const gObj = lib[att.objectId]!;
        const mid = { x: (w.start.x + w.end.x) / 2, y: (w.start.y + w.end.y) / 2 };
        // A SPINE read the endpoints itself and is already in world position — hand it the host and push its
        // prisms through untouched, exactly as the 2D branch does.
        if (objIsSpine(gObj)) {
          const hostPts = [w.start, w.end].map((p) => ({ x: (p.x - mid.x) / pixelsPerMeter, y: (p.y - mid.y) / pixelsPerMeter }));
          const sp = evalParametricPrisms(objText(gObj), mid, pixelsPerMeter, vp(att.params), hostPts, resolveObjectDef, att.childParams);
          if (sp.length) out.push({ id: `pobj-seg-${w.id}-${att.id}`, prisms: sp, host: { kind: "segment", id: w.id, attId: att.id }, bind: bindOf(att, lib[att.objectId]) });
          continue;
        }
        const prisms = evalParametricPrisms(objText(gObj), mid, pixelsPerMeter, vp({ ...att.params, rotation: 0 }), undefined, resolveObjectDef, att.childParams);
        if (!prisms.length) continue;
        const gb = polysBBox(prisms.flatMap((p) => [p.bottom, p.top]));
        if (!gb) continue;
        const sxF = L / Math.max(1e-6, gb.maxX - gb.minX);
        const gcx = (gb.minX + gb.maxX) / 2, gcy = (gb.minY + gb.maxY) / 2;
        const ux = dx / L, uy = dy / L;
        const tp = (p: Point): Point => {
          const lx = (p.x - gcx) * sxF, ly = p.y - gcy;
          return { x: mid.x + ux * lx + nx * ly, y: mid.y + uy * lx + ny * ly };
        };
        out.push({ id: `pobj-seg-${w.id}-${att.id}`, prisms: prisms.map((p) => ({ ...p, bottom: p.bottom.map(tp), top: p.top.map(tp) })), host: { kind: "segment", id: w.id, attId: att.id }, bind: bindOf(att, lib[att.objectId]) });
      }
    }
    return out;
  };
  const floorWallMeshes = useMemo<HostedFlowMesh[]>(
    () => (is3dOpen ? buildFloorWallMeshes(history.state, miteredPolygons, roomInscribedRects, wallCarveFootprints) : []),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- buildFloorWallMeshes reads pixelsPerMeter / isLayerVisible, listed
    [history.state.rooms, history.state.walls, history.state.objectLibrary, miteredPolygons, pixelsPerMeter, roomInscribedRects, wallCarveFootprints, isLayerVisible, is3dOpen, uiRenderMode]);
  // ── Attached SPINE objects whose solids are NOT straight prisms — a bike's tubes and wheels, a car's lofted
  // body, anything booleaned. `FlowMeshPrism` is a bottom outline plus a top outline, so it cannot hold them;
  // the 3D canvas already draws general FACE LISTS for a Render node's Polyhedron row, and this feeds attached
  // objects down that same channel as `PrimMass3D` entries.
  //
  // Exactly the meshes the prism path could not take appear here (see spineSolids) — never both, or a solid
  // would be drawn twice and z-fight with itself. Faces arrive in ANCHOR-RELATIVE plan metres, so the mapping
  // is the Polyhedron row's own: plan [x, y, z] → scene (x, z, y), with the host's position as the transform.
  // Python objects run asynchronously (Pyodide in a worker); bump this when a result lands so the views pick it up.
  const [pyTick, setPyTick] = useState(0);
  useEffect(() => onPythonResult(() => setPyTick((t) => t + 1)), []);
  const spineObjectMasses = useMemo<PrimMass3D[]>(() => {
    // 3D-only output: with the 3D view closed nothing reads it, and resolving every object's solids on a big
    // plan cost ~10 s per load (same gate as the node-object prisms above).
    if (!is3dOpen) return [];
    const lib = history.state.objectLibrary ?? {};
    const ppm = pixelsPerMeter || 1;
    const out: PrimMass3D[] = [];
    const push = (idBase: string, anchorPx: Point, hostPts: Point[] | undefined, att: { objectId: string; params: Record<string, number | string | boolean>; id: string }, hostRef: Omit<MeshHost, "attId">) => {
      const host: MeshHost = { ...hostRef, attId: att.id };
      const obj = lib[att.objectId];
      if (objIsPython(obj)) {
        // Object-local metres (+x across, +y back→front, +z up) → scene metres (x, y up, z = plan Y), turned by
        // the instance's `rotation` (degrees, plan) about its anchor. Like spine objects, Python runs only in Full.
        if (renderModeOf(vp(att.params)) !== "Full") return;
        const res = getPythonResult(obj, att.params, hostPts);
        if (!res) return;
        const rot = pythonRotation(obj, att.params), c = Math.cos(rot), sn = Math.sin(rot);
        const ax = anchorPx.x / ppm, az = anchorPx.y / ppm;
        res.meshes.forEach((m, i) => {
          const src = m.positions, pos = new Float32Array(src.length);
          for (let k = 0; k < src.length; k += 3) {
            const lx = src[k], ly = src[k + 1], lz = src[k + 2];
            pos[k] = ax + lx * c - ly * sn;
            pos[k + 1] = lz;
            pos[k + 2] = az + lx * sn + ly * c;
          }
          out.push({
            id: `py-${idBase}-${att.id}-${i}`, host, materialPath: rowMaterialPath(bindOf(att, lib[att.objectId]), m.name), shape: "mesh", layer: m.name,
            length: 0, breadth: 0, height: 0, radius: 0, radiusTop: 0, topLength: 0, topBreadth: 0, tubeRadius: 0, arcDeg: 360,
            mesh: { positions: pos, indices: m.indices },
            color: m.color ?? "#cbd5e1",
            transform: { tx: 0, ty: 0, tz: 0, rx: 0, ry: 0, rz: 0, mx: 1, my: 1, mz: 1 },
          });
        });
        return;
      }
      if (!objIsSpine(obj)) return;
      const r = resolveSpineObject(JSON.stringify(obj), anchorPx, ppm, vp(att.params), hostPts);
      if (!r) return;
      const { faceMeshes } = spineSolids(r.meshes, anchorPx, ppm);
      faceMeshes.forEach((m, i) => {
        const faces = m.faces.map((ring) => ring.map((q) => [q[0], q[2], q[1]]));
        if (!faces.length) return;
        out.push({
          id: `spine-${idBase}-${att.id}-${m.id || i}`, host, materialPath: rowMaterialPath(bindOf(att, lib[att.objectId]), m.name, m.material), layer: m.name,
          shape: "polyhedron",
          length: 0, breadth: 0, height: 0, radius: 0,
          radiusTop: 0, topLength: 0, topBreadth: 0, tubeRadius: 0, arcDeg: 360,
          faces,
          color: m.color,
          transform: { tx: anchorPx.x / ppm, ty: 0, tz: anchorPx.y / ppm, rx: 0, ry: 0, rz: 0, mx: 1, my: 1, mz: 1 },
        });
      });
    };
    // NODE-hosted: the node IS the anchor, so the host is the local origin.
    for (const node of wallNodes) {
      for (const att of (history.state.nodeMeta ?? {})[node.stableKey]?.attachments ?? []) {
        push(`node-${node.stableKey}`, { x: node.x, y: node.y }, [{ x: 0, y: 0 }], att, { kind: "node", id: node.stableKey });
      }
    }
    // SEGMENT-hosted: anchored at the midpoint, the two endpoints handed over as the host.
    for (const w of history.state.walls) {
      for (const att of w.attachments ?? []) {
        const mid = { x: (w.start.x + w.end.x) / 2, y: (w.start.y + w.end.y) / 2 };
        push(`seg-${w.id}`, mid, [w.start, w.end].map((p) => ({ x: (p.x - mid.x) / ppm, y: (p.y - mid.y) / ppm })), att, { kind: "segment", id: w.id });
      }
    }
    // SPACE-hosted: anchored at the centroid, the outline handed over.
    for (const room of history.state.rooms) {
      if (!room.attachments?.length || room.points.length < 3) continue;
      const c = polygonCentroid(room.points);
      const hostLocal = room.points.map((p) => ({ x: (p.x - c.x) / ppm, y: (p.y - c.y) / ppm }));
      for (const att of room.attachments) push(`room-${room.id}`, c, hostLocal, att, { kind: "space", id: room.id });
    }
    return out;
  }, [history.state.objectLibrary, history.state.nodeMeta, history.state.walls, history.state.rooms, wallNodes, pixelsPerMeter, is3dOpen, pyTick, uiRenderMode]);

  // Everything the 3D view shows on the generic mesh channel: Flow "Mesh to 3D" output + node-attached
  // parametric-object meshes + Space-floor / Segment-wall meshes.
  const meshPreviewAll = useMemo<HostedFlowMesh[] | undefined>(() => {
    const all = [...(flowMeshPreview ?? []), ...parametricObjectMeshes, ...floorWallMeshes];
    return all.length ? all : undefined;
  }, [flowMeshPreview, parametricObjectMeshes, floorWallMeshes]);
  // "Views" mode: the four orthographic elevations of the canvas plan (walls + door/window openings),
  // projected from the live wall graph. Plan stays in the centre; Back top / Front bottom / Left / Right.
  /** Live Place Object previews → temporary placement-preview walls (one quad per object) merged into
   *  the 3D model so the existing `placementGroups` extrudes them as 3D primitives BEFORE the flow is
   *  committed. Carries each object's kind/height/clearance so the primitive matches the committed one.
   *  Corner order (p0→p1 = length edge along the boundary, p1→p2 = breadth) matches buildCornersAtEdge,
   *  so the 3D solver picks walls[0]/walls[1] correctly. These live only in the 3D model prop — never
   *  in history — so they don't affect room detection or undo. */
  const flowPlacementPreviewWalls = useMemo<Wall[]>(() => {
    const walls: Wall[] = [];
    for (const item of flowPreview) {
      if (item.tool !== "place-object" || !item.placeObjects) continue;
      item.polygons.forEach((quad, pi) => {
        const meta = item.placeObjects![pi];
        if (!meta || quad.length < 4) return;
        const objId = `flowprev-${item.nodeId}-${pi}`;
        for (let i = 0; i < 4; i++) {
          walls.push({
            id: `${objId}-w${i}`,
            start: quad[i],
            end: quad[(i + 1) % 4],
            thickness: 2,
            color: item.color,
            segmentType: "wall",
            isPlacementPreview: true,
            placementObjectId: objId,
            placementKind: meta.kind as Wall["placementKind"],
            placementHeightM: meta.heightM,
            placementClearanceM: meta.clearanceM,
          });
        }
      });
    }
    return walls;
  }, [flowPreview]);
  /** Flow "Node to Object" placements → the same placement-preview walls Place Object uses, so each placed
   *  object renders as its 3D primitive (by kind) in the 3D view — just like furniture along a boundary. */
  const flowNodeObjectPreviewWalls = useMemo<Wall[]>(() => {
    const KIND_H: Record<string, number> = {
      bed: 0.5, sofa: 0.8, table: 0.75, chair: 0.9, desk: 0.75, wardrobe: 2.0, bookshelf: 1.8,
      bench: 0.45, fridge: 1.7, toilet: 0.75, bathtub: 0.6, "tv-unit": 0.5, piano: 1.0, wc: 0.75,
    };
    const walls: Wall[] = [];
    for (const item of flowPreview) {
      if (item.tool !== "node-to-object" || !item.objectPlacements) continue;
      item.objectPlacements.forEach((pl, pi) => {
        const quad = pl.quad;
        if (!quad || quad.length < 4) return;
        const objId = `flownodeobj-${item.nodeId}-${pi}`;
        for (let i = 0; i < 4; i++) {
          walls.push({
            id: `${objId}-w${i}`,
            start: quad[i],
            end: quad[(i + 1) % 4],
            thickness: 2,
            color: item.color,
            segmentType: "wall",
            isPlacementPreview: true,
            objectPrimitive3d: true,
            placementObjectId: objId,
            placementKind: pl.kind as Wall["placementKind"],
            placementHeightM: KIND_H[pl.kind] ?? 0.8,
          });
        }
      });
    }
    return walls;
  }, [flowPreview]);
  /** Whether the 3D view is in 2D-Symbol placement mode (the only mode that renders placed objects as
   *  primitives). Gates injecting the live placement-preview walls — in polygon/rendered mode those
   *  walls would draw as boxy wall meshes instead. Mirrors the placementMode prop computed below. */
  const placement3dSymbolMode = layerVisibility.fillingUnion || layerVisibility.placement2dSymbol;
  /** Live BSP partition preview → temporary wall/door/window segments merged into the 3D model so the
   *  partition extrudes as walls with door (inner) / window (outer) openings BEFORE committing. These
   *  live only in the 3D model prop — never in history — so they don't affect room detection or undo. */
  const flowBspPreviewWalls = useMemo<Wall[]>(() => {
    const walls: Wall[] = [];
    const thickness = Math.max(2, 0.1 * pixelsPerMeter); // ~10 cm preview partition
    for (const item of flowPreview) {
      if ((item.tool !== "bsp" && item.tool !== "treemap") || !item.bspWalls) continue;
      item.bspWalls.forEach((seg, i) => {
        const L = Math.hypot(seg.b.x - seg.a.x, seg.b.y - seg.a.y);
        if (L < 1) return;
        walls.push({
          id: `flowbsp-${item.nodeId}-${i}`,
          start: seg.a,
          end: seg.b,
          thickness,
          color: "#cbd5e1",
          method: "center",
          segmentType: seg.kind, // "wall" | "door" | "window" → 3D renders openings for door/window
        });
      });
    }
    return walls;
  }, [flowPreview, pixelsPerMeter]);

  /** Flow "Live" mode: materialise every SPACE-PRODUCING node's output as REAL, editable canvas geometry
   *  that regenerates on every parameter change — the alternative to preview-then-Run. A node opts in via
   *  its `FlowToolDef.materialisesSpace` flag (declared in its .node.json), so this is fully GENERAL — no
   *  hardcoded tool list; enabling a new node = one JSON flag. Each such node's live polygon(s) become a
   *  tagged Space (Room.flowOwner) plus their boundary as tagged wall segments (Wall.flowOwner), all wiped
   *  + redrawn each pass so the result tracks the params in real time. Owned geometry is kept INERT to
   *  auto-room detection + suppression (see the autoRooms / suppressors filters), so materialising it never
   *  feeds back into the flow's source. Chaining (inset → optimise-rect) rides the flow's own pure
   *  evaluator — each node's `polygons` is already computed inside its upstream — so no committed-geometry
   *  round-trip. Written via history.replace (transient — no undo entry per scrub). */
  const liveFlowSigRef = useRef<string>("");
  /** Same guard for the Export to Canvas eye-previews: identical geometry → no write at all, so the preview
   *  effect can safely run on every graph tick. */
  const exportPreviewSigRef = useRef<string>("");
  /** Export to Canvas nodes whose preview is held back because it is currently identical to what they just
   *  committed (nodeId → the committed geometry's fingerprint). Cleared as soon as the geometry changes, so
   *  editing the flow after a Commit brings the preview straight back. */
  const exportPreviewSuppressedRef = useRef<Map<string, string>>(new Map());
  /** Signature of every host-aware pipeline object attached to a (non-owned) Space — its host id + host
   *  polygon + objectId + params. Changes when a Site/Floor is attached, its params edited, or its host
   *  Space moved/resized, so the Live-materialise effect below re-runs and rebuilds the committed per-op
   *  Spaces. Excludes flowOwner rooms (the effect's own output) so it never self-triggers. */
  const liveAttachmentsSig = useMemo(() =>
    history.state.rooms
      .filter((r) => !r.flowOwner && (r.attachments?.length ?? 0) > 0 && r.points.length >= 3)
      .map((r) => `${r.id}#${r.points.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join("|")}#${(r.attachments ?? []).map((a) => `${a.id}:${a.objectId}:${JSON.stringify(a.params)}`).join(",")}`)
      .join(";"),
    [history.state.rooms]);
  /** Any host-aware pipeline object attached to a Space? Lets the Flow "Live" toggle be enabled even with an
   *  empty flow, so an attached Site can be live-committed to per-op Space layers on its own. */
  const hasLivePipelineAttachment = useMemo(() => {
    const lib = history.state.objectLibrary ?? {};
    return history.state.rooms.some((r) => !r.flowOwner && (r.attachments ?? []).some((a) => {
      const obj = lib[a.objectId];
      // A spine is host-aware by construction — it reads the host on `P` — so it never needs the rules probe.
      return objIsSpine(obj) || (!!obj?.geometry && pobjIsHostAware(JSON.stringify(obj)));
    }));
  }, [history.state.rooms, history.state.objectLibrary]);
  /** One canvas wall from a flow-drawn segment. A Network row carries what its segments should BECOME —
   *  thickness, `segmentType`, and the segment-hosted library object each one hosts — so a generated plan
   *  arrives as editable ELEMENTS (a Door segment hosting door.json, a Window segment hosting window.json)
   *  rather than as anonymous lines. Nodes that carry no such metadata (Line, Polygon → segments) keep the
   *  canvas drawing defaults, exactly as before. */
  const flowSegmentWall = useCallback(
    (id: string, a: Point, b: Point, meta: FlowPreviewItem["segMeta"], layerId: string, owner?: string, segIndex?: number): Wall => ({
      id,
      start: { x: a.x, y: a.y },
      end: { x: b.x, y: b.y },
      // An edge that carried its own thickness overrides the row's uniform one — that is what makes a door
      // or window exactly as thick as the wall it sits in. Mismatched widths mitre into a wedge at the jamb,
      // which pinches the wall band on either side of the opening.
      thickness: meta
        ? Math.max(1, ((segIndex != null ? meta.thicknessMPer?.[segIndex] : undefined) ?? meta.thicknessM) * pixelsPerMeter)
        : wallThickness,
      color: wallColor,
      method: "center",
      ...(meta?.segmentType ? { segmentType: meta.segmentType } : {}),
      // How the bands meet at shared endpoints. Unset = the canvas view decides (what a hand-drawn wall
      // does); "mitered-union" merges every connected run into one seamless outline, which is what makes a
      // generated plan read as masonry rather than as a row of separate rectangles.
      // A BUFFERED band takes its fill style from `mode` (the Display block's Outlined / Filled), and pins the
      // seamless join separately in `bufferJoin` — the two are independent choices there. A plain wall band
      // has no such split, so `mode` carries the join itself.
      ...(meta?.display
        ? { mode: (meta.fill === "filled" ? "fill" : "outline") as WallMode, ...(meta.wallMode === "mitered-union" ? { bufferJoin: "mitered-union" as const } : {}) }
        : meta?.wallMode ? { mode: meta.wallMode as WallMode } : {}),
      // Display mode — `bufferStyle` set is exactly what the Display block writes when you pick "Buffered",
      // so the row arrives banded rather than as a thin line waiting to be converted wall by wall.
      ...(meta?.display ? { bufferStyle: meta.display.style, ...(meta.display.asSpace ? { asSpace: true } : {}) } : {}),
      // The row builds its own 3D (a Polyhedron from the mitred rings) — keep the canvas out of it.
      ...(meta?.extrude3d === false ? { noExtrude3d: true } : {}),
      // Poché hatch drawn by the CANVAS band rather than by the hosted Wall object — see `segMeta.hatch`.
      ...(meta?.hatch
        ? { hatch: true, hatchStyle: meta.hatch.style, hatchSpacing: meta.hatch.spacing, hatchAngle: meta.hatch.angle, hatchWeight: meta.hatch.weight }
        : {}),
      // A door / window segment is an OPENING: the band renders as a gap and the hosted object draws the leaf
      // or the frame, which is how an opening drawn by hand behaves. A wall segment keeps its band — the Wall
      // object sits exactly on it (same length, same thickness once bound) and adds the poché hatch.
      ...(meta?.segmentType === "door" || meta?.segmentType === "window" ? { isObjectOpening: true } : {}),
      // The attachment is what makes it BIM: the object reads its geometry from this host segment, so a
      // 0.9 m door segment is a 0.9 m door, and its params are editable per instance in Properties.
      // `objectParams` binds the object's own fields to the row — a Wall object's thickness to the segment's.
      // The primary hosted object, then any further ones the row asked for. A door segment hosts the door
      // AND the wall above its lintel; a window hosts the frame AND the wall below its sill and above its
      // head. Ids stay distinct per attachment or the later ones overwrite the first.
      ...(meta?.objectId || meta?.extraObjects?.length
        ? {
            attachments: [
              ...(meta?.objectId ? [{ id: `${id}:att`, objectId: meta.objectId, params: { ...(meta.objectParams ?? {}) }, t: 0.5 }] : []),
              ...(meta?.extraObjects ?? []).map((o, oi) => ({ id: `${id}:att${oi + 2}`, objectId: o.objectId, params: { ...(o.params ?? {}) }, t: 0.5 })),
            ],
          }
        : {}),
      layerId,
      ...(owner ? { flowOwner: owner } : {}),
    }),
    [pixelsPerMeter, wallThickness, wallColor],
  );

  useEffect(() => {
    const h = historyRef.current;
    // A materialised object NODE (Place Object) is a degenerate wall (flowOwner) + a nodeMeta entry keyed
    // "flowliveobj:…"; those keys are how owned node metadata is found for cleanup.
    const OWNED_META = FLOW_LIVE_OBJ_PREFIX;
    const stripOwnedMeta = (meta: Record<string, NodeMeta> | undefined): Record<string, NodeMeta> =>
      Object.fromEntries(Object.entries(meta ?? {}).filter(([k]) => !k.includes(OWNED_META)));
    const hadOwnedMeta = Object.keys(h.state.nodeMeta ?? {}).some((k) => k.includes(OWNED_META));
    // An Export to Canvas eye-preview is ALSO `flowOwner` tagged (so it stays inert to auto-room detection),
    // but it belongs to `setFlowExportPreview`, not to this effect — Live must leave it standing whether it
    // is on or off, or toggling Live would silently erase another node's visible output.
    const isMine = (e: { id: string; flowOwner?: string }) => Boolean(e.flowOwner) && !isExportPreviewEntity(e);
    const hadOwned = h.state.rooms.some(isMine) || h.state.walls.some(isMine) || hadOwnedMeta;

    // Live OFF → drop all owned geometry + object nodes (back to the preview overlay) in one replace.
    if (!liveFlow) {
      liveOwnedNodeIdsRef.current = new Set();
      liveOwnedAttIdsRef.current = new Set();
      liveFlowSigRef.current = "";
      if (hadOwned) h.replace({ ...h.state, rooms: h.state.rooms.filter((r) => !isMine(r)), walls: h.state.walls.filter((w) => !isMine(w)), nodeMeta: stripOwnedMeta(h.state.nodeMeta) });
      return;
    }

    // Ensure a per-node "Live" layer WITHOUT hijacking the active layer (ensureLayerInLayers would call
    // setActiveLayerId on every scrub tick — not wanted here).
    const palette = ["#ef4444", "#f97316", "#eab308", "#22c55e", "#06b6d4", "#3b82f6", "#a855f7", "#ec4899"];
    const ensureLiveLayer = (list: NonNullable<FloorPlanModel["layers"]>, slug: string, name: string): NonNullable<FloorPlanModel["layers"]> => {
      if (list.some((l) => l.id === slug)) return list;
      const order = list.reduce((m, l) => Math.max(m, l.order), 0) + 1;
      return [...list, { id: slug, name, color: palette[list.length % palette.length], visible: true, locked: false, order }];
    };

    // Materialise every node flagged `materialisesSpace` → owned Space + boundary walls, on a per-node
    // "Live" layer. `base` (the node id sans any "__piece" suffix) owns the geometry; the geometry ids key
    // off the FULL item id + piece index so multi-output nodes (split → several pieces) don't collide.
    const ownedNodeIds = new Set<string>();
    const ownedRooms: Room[] = [];
    const ownedWalls: Wall[] = [];
    const ownedNodeMeta: Record<string, NodeMeta> = {};
    let layers = h.state.layers ?? [];
    for (const item of flowPreview) {
      // Place Object → materialise selectable object NODES (a degenerate wall + a nodeMeta attachment
      // carrying the real parametric object) at each placement, so the boundary stays a dummy preview while
      // the furniture becomes live, editable nodes. Mirrors the asObjectNodes commit (~13007) but idempotent
      // (deterministic ids) + tagged for Live cleanup.
      if (item.tool === "place-object" && item.placeObjects?.length) {
        const base = item.nodeId.split("__")[0];
        const layerId = `flow-live-${base}`;
        let made = 0;
        item.placeObjects.forEach((po, i) => {
          const corners = item.polygons[i];
          if (!corners || corners.length < 4) return;
          const cx = (corners[0].x + corners[1].x + corners[2].x + corners[3].x) / 4;
          const cy = (corners[0].y + corners[1].y + corners[2].y + corners[3].y) / 4;
          const rotDeg = (Math.atan2(corners[1].y - corners[0].y, corners[1].x - corners[0].x) * 180) / Math.PI;
          const rotNorm = ((rotDeg % 360) + 360) % 360;
          const wallId = `${OWNED_META}${base}:${po.ringIndex ?? 0}:${po.srcIndex}`;
          const stableKey = [`${wallId}:start`, `${wallId}:end`].sort().join("|");
          const pobj = po.objectId ? findLibraryObject(po.objectId) : undefined;
          if (pobj) {
            // Anchor so the object's measured bbox centre lands on the footprint centre (bbox centre can be
            // offset from the anchor); rotate that offset into edge space — same math as the commit.
            const rad = (rotDeg * Math.PI) / 180, cosR = Math.cos(rad), sinR = Math.sin(rad);
            const m = measureParametricObject(pobj.meta.id);
            const offX = (m?.offsetXM ?? 0) * pixelsPerMeter, offY = (m?.offsetYM ?? 0) * pixelsPerMeter;
            const ax = cx - (offX * cosR - offY * sinR), ay = cy - (offX * sinR + offY * cosR);
            const attParams: Record<string, number | string | boolean> = {};
            for (const pr of pobj.parameters) attParams[pr.key] = pr.default;
            attParams.rotation = rotNorm;
            attParams.wallOffset = 0;
            attParams.clearance = Math.max(0, po.clearanceM);
            ownedWalls.push({ id: wallId, start: { x: ax, y: ay }, end: { x: ax, y: ay }, thickness: 0.5, color: "#334155", dashed: false, mode: "line", method: "center", segmentType: "wall", layerId, flowOwner: base });
            ownedNodeMeta[stableKey] = { label: pobj.meta.name, attachments: [{ id: `${wallId}:att`, objectId: pobj.meta.id, params: attParams, t: 0, flip: false }] };
            made += 1;
          } else {
            // Hard-coded furniture kind (no .pobj) → an object-kind node sized from the footprint quad.
            const wPx = Math.hypot(corners[1].x - corners[0].x, corners[1].y - corners[0].y);
            const hPx = Math.hypot(corners[2].x - corners[1].x, corners[2].y - corners[1].y);
            ownedWalls.push({ id: wallId, start: { x: cx, y: cy }, end: { x: cx, y: cy }, thickness: 0.5, color: "#334155", dashed: false, mode: "line", method: "center", segmentType: "wall", layerId, flowOwner: base });
            ownedNodeMeta[stableKey] = { type: "object", objectKind: po.kind === "fridge" ? "refrigerator" : po.kind, objWidth: wPx / pixelsPerMeter, objHeight: hPx / pixelsPerMeter, objOffsetBottom: Math.max(0, po.clearanceM), objRotation: rotNorm, objAnchor: "center" };
            made += 1;
          }
        });
        if (made > 0) { ownedNodeIds.add(base); layers = ensureLiveLayer(layers, layerId, "Live · Objects"); }
        continue;
      }
      // SEGMENT-producing nodes (Network, Line, Polyline, Arc) → one owned wall per consecutive point
      // pair. Canvas nodes ARE wall endpoints in this model, so junctions materialise automatically where
      // segments share a point — a graph comes through as nodes AND segments without creating either
      // explicitly. Runs before the Space branch because these outputs are open strokes, not room faces.
      if (FLOW_TOOLS[item.tool]?.materialisesSegments && item.polygons.length > 0) {
        const base = item.nodeId.split("__")[0];
        // A Network row names its own layer; anything else keeps the per-node "Live · <tool>" one.
        const meta = item.segMeta;
        const layerId = meta?.layer ? `flow-live-${slugifyLayer(meta.layer)}` : `flow-live-${base}`;
        const label = meta?.layer ?? `Live · ${FLOW_TOOLS[item.tool]?.label ?? "Segments"}`;
        // PER-EDGE TYPE DISPATCH. When the row carries a `byType` map, an edge whose graph `type` is a key
        // in it is materialised with THAT meta — its own object, layer, thickness and display — instead of
        // the row's. This is what lets one Network node draw exterior walls, interior walls, doors and
        // windows off a single merged graph. An edge with no type, or a type the map does not mention,
        // falls through to the row's own meta, so an ordinary Network row behaves exactly as before.
        //
        // The layer follows the edge, so ONE row can populate several Live layers; each is created on
        // demand rather than up front, and an unused type in the map creates none.
        const metaFor = (pi: number) => {
          const t = meta?.typePer?.[pi];
          return (t && meta?.byType?.[t]) || meta;
        };
        const usedLayers = new Map<string, string>();
        let made = 0;
        item.polygons.forEach((pl, pi) => {
          const em = metaFor(pi);
          const elayer = em?.layer ? `flow-live-${slugifyLayer(em.layer)}` : layerId;
          const elabel = em?.layer ?? label;
          // A CLOSED ring (Polygon fed into a segment-producer) wraps back to its first point; an open
          // stroke stops at the last pair.
          const closed = !item.openPath && pl.length >= 3;
          const last = closed ? pl.length : pl.length - 1;
          for (let i = 0; i < last; i++) {
            const a = pl[i], b = pl[(i + 1) % pl.length];
            if (Math.hypot(b.x - a.x, b.y - a.y) < 1) continue; // skip degenerate/duplicate points
            ownedWalls.push(flowSegmentWall(`flowlive:${item.nodeId}:seg:${pi}:${i}`, a, b, em, elayer, base, pi));
            usedLayers.set(elayer, elabel);
            made += 1;
          }
        });
        // Claim ownership (→ overlay suppression + a Live layer) only when segments were actually made,
        // so an empty node keeps showing its preview overlay.
        if (made > 0) {
          ownedNodeIds.add(base);
          for (const [lid, lbl] of usedLayers) layers = ensureLiveLayer(layers, lid, lbl);
        }
        continue;
      }
      // Only space-producing nodes, and never OPEN polylines (openPath = graph/centerline output) — those
      // aren't room faces.
      if (!FLOW_TOOLS[item.tool]?.materialisesSpace || item.openPath || item.polygons.length === 0) continue;
      const base = item.nodeId.split("__")[0];
      // A `layer` on the item (the Polygon node's Layer param) names the canvas layer explicitly — several
      // polygons sharing a name land on ONE layer; blank falls back to the node's own per-node Live layer.
      const customLayer = typeof item.layer === "string" && item.layer.trim() ? item.layer.trim() : null;
      const layerId = customLayer ?? `flow-live-${base}`;
      const label = FLOW_TOOLS[item.tool]?.label ?? "Space";
      // Does this node own the boundary of the faces it makes? Graph to Spaces does not — it reads a graph
      // the Network nodes have already drawn, so re-emitting its rings would lay a default-thickness slab
      // over every real wall AND across every door and window, since a room face closes through its openings.
      const ownsBoundaryEdges = FLOW_TOOLS[item.tool]?.materialisesSpaceEdges !== false;
      // Group the node's rings into outer boundaries + holes: a ring whose centroid lies inside a
      // strictly-larger ring is that ring's HOLE (e.g. Corridoor "insetted" = an outer loop carved by a
      // courtyard). Most nodes emit only disjoint outers, so this is a no-op for them; skipped past 30 rings
      // (mesh / fine Voronoi have no holes anyway) to keep the O(n²) containment scan cheap.
      const rings = item.polygons.filter((p) => p.length >= 3); // drop 2-pt edges (skeleton centerlines, non-Euclidean Voronoi)
      const areaOf = (r: Point[]) => Math.abs(polygonArea(r));
      const centroidIn = (r: Point[], poly: Point[]) => {
        const c = polygonCentroid(r); let inside = false;
        for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
          const a = poly[i], b = poly[j];
          if (((a.y > c.y) !== (b.y > c.y)) && (c.x < (b.x - a.x) * (c.y - a.y) / ((b.y - a.y) || 1e-9) + a.x)) inside = !inside;
        }
        return inside;
      };
      const parent = rings.map((r, i) => {
        if (rings.length > 30) return -1;
        let best = -1, bestArea = Infinity;
        rings.forEach((o, j) => { if (j !== i && areaOf(o) > areaOf(r) && areaOf(o) < bestArea && centroidIn(r, o)) { best = j; bestArea = areaOf(o); } });
        return best;
      });
      // A Space can host a parametric object the same way a segment can. When the node names one, every
      // room it materialises arrives carrying it — the object's OWN defaults filled in first, then the
      // node's bindings over the top, which is the order flowSegmentWall and Place Object both use. An
      // unknown id attaches nothing rather than a broken reference.
      const spaceObj = item.spaceMeta?.objectId ? findLibraryObject(item.spaceMeta.objectId) : undefined;
      const spaceObjParams: Record<string, number | string | boolean> | undefined = spaceObj
        ? { ...Object.fromEntries(spaceObj.parameters.map((pr) => [pr.key, pr.default])), ...(item.spaceMeta?.objectParams ?? {}) }
        : undefined;
      let produced = 0;
      rings.forEach((outer, ri) => {
        if (parent[ri] >= 0) return; // this ring is a hole of another ring → not a standalone Space
        const holes = rings.filter((_, hi) => parent[hi] === ri);
        produced += 1;
        ownedRooms.push({
          id: `flowlive:${item.nodeId}:${ri}`,
          points: outer.map((p) => ({ x: p.x, y: p.y })),
          ...(holes.length ? { holes: holes.map((hr) => hr.map((p) => ({ x: p.x, y: p.y }))) } : {}),
          layerId, flowOwner: base,
          fill: "rgba(34,197,94,0.2)", stroke: "#16A34A",
          roomType: "room", label, showLabel: true,
          ...(spaceObj && spaceObjParams
            ? { attachments: [{ id: `flowlive:${item.nodeId}:${ri}:att`, objectId: spaceObj.meta.id, params: spaceObjParams, t: 0 }] }
            : {}),
        });
        // Walls for the outer boundary AND each hole boundary (both are corridor edges).
        if (ownsBoundaryEdges) [outer, ...holes].forEach((ring, hk) => {
          for (let i = 0; i < ring.length; i++) {
            const a = ring[i], b = ring[(i + 1) % ring.length];
            if (Math.hypot(b.x - a.x, b.y - a.y) < 1) continue;
            ownedWalls.push({
              id: `flowlive:${item.nodeId}:${ri}:${hk}:${i}`,
              start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
              thickness: wallThickness, color: wallColor, method: "center",
              layerId, flowOwner: base,
            });
          }
        });
      });
      // Claim ownership (→ overlay suppression + a Live layer) ONLY when this node actually produced a
      // closed Space; otherwise its overlay must keep showing (skeleton centerlines, Voronoi edges, …).
      if (produced > 0) { ownedNodeIds.add(base); layers = ensureLiveLayer(layers, layerId, customLayer ?? `Live · ${label}`); }
    }
    liveOwnedNodeIdsRef.current = ownedNodeIds;

    // ── Attached host-aware pipeline objects (Site/Floor/Massing) → materialise each pipeline OP's footprint
    //    as owned Spaces on its OWN layer ("<Object> · Inset / Split / Optimise"), so an attached Site's
    //    inset → split → optimise steps become real, per-layer Spaces that track the object's params live —
    //    the attach-object analogue of a flow's stepwise commit. Non-host-aware objects (staircase, furniture)
    //    and objects without a pipeline keep their display-only overlay. ──
    const ownedAttIds = new Set<string>();
    const objLib = h.state.objectLibrary ?? {};
    for (const room of h.state.rooms) {
      if (room.flowOwner || room.points.length < 3 || (room.attachments?.length ?? 0) === 0) continue;
      const c = polygonCentroid(room.points);
      const hostLocal = room.points.map((p) => ({ x: (p.x - c.x) / pixelsPerMeter, y: (p.y - c.y) / pixelsPerMeter }));
      for (const att of room.attachments ?? []) {
        const obj = objLib[att.objectId];
        if (!obj?.geometry) continue;
        const defText = objText(obj);
        if (!pobjIsHostAware(defText)) continue; // non-host-aware → keep the fit-to-rect overlay
        let steps: { op: string; polygons: Point[][] }[] = [];
        try { steps = evalParametricPipelineSteps(defText, c, pixelsPerMeter, att.params, hostLocal, resolveObjectDef, att.childParams); } catch { steps = []; }
        if (steps.length === 0) continue;
        const ownerBase = `pobjlive:${room.id}:${att.id}`;
        const objName = obj.meta?.name ?? "Object";
        const opSeen = new Map<string, number>(); // per-op-name counter → stable layer id if an op repeats
        let produced = 0;
        for (const step of steps) {
          const rings = step.polygons.filter((p) => p.length >= 3);
          if (rings.length === 0) continue;
          const seen = opSeen.get(step.op) ?? 0; opSeen.set(step.op, seen + 1);
          const opLabel = step.op.split(/[-_\s]+/).filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
          const layerId = `pobjlive-${room.id}-${att.id}-${step.op}${seen ? `-${seen}` : ""}`;
          rings.forEach((ring, ri) => {
            ownedRooms.push({
              id: `${ownerBase}:${step.op}:${seen}:${ri}`,
              points: ring.map((p) => ({ x: p.x, y: p.y })),
              layerId, flowOwner: ownerBase,
              fill: "rgba(34,197,94,0.2)", stroke: "#16A34A",
              roomType: "room", label: `${objName} · ${opLabel}`, showLabel: true,
            });
            for (let i = 0; i < ring.length; i++) {
              const a = ring[i], b = ring[(i + 1) % ring.length];
              if (Math.hypot(b.x - a.x, b.y - a.y) < 1) continue;
              ownedWalls.push({ id: `${ownerBase}:${step.op}:${seen}:${ri}:${i}`, start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y }, thickness: wallThickness, color: wallColor, method: "center", layerId, flowOwner: ownerBase });
            }
          });
          layers = ensureLiveLayer(layers, layerId, `${objName} · ${opLabel}`);
          produced += 1;
        }
        if (produced > 0) ownedAttIds.add(att.id);
      }
    }
    liveOwnedAttIdsRef.current = ownedAttIds;

    // Skip the write when the owned geometry is unchanged (stable params) — avoids needless re-renders.
    // Cover rooms (points), walls / object-node anchors, and each object node's rotation.
    const sig = [
      ...ownedRooms.map((r) => `${r.id}#${r.points.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join("|")}`),
      ...ownedWalls.map((w) => `${w.id}@${w.start.x.toFixed(1)},${w.start.y.toFixed(1)}`),
      ...Object.entries(ownedNodeMeta).map(([k, v]) => `${k}~${v.attachments?.[0]?.params?.rotation ?? v.objRotation ?? 0}`),
    ].join(";");
    const nowHasOwned = ownedRooms.length > 0 || ownedWalls.length > 0 || Object.keys(ownedNodeMeta).length > 0;
    if (sig === liveFlowSigRef.current && hadOwned === nowHasOwned) return;
    liveFlowSigRef.current = sig;
    h.replace({
      ...h.state,
      layers,
      rooms: [...h.state.rooms.filter((r) => !isMine(r)), ...ownedRooms],
      walls: [...h.state.walls.filter((w) => !isMine(w)), ...ownedWalls],
      nodeMeta: { ...stripOwnedMeta(h.state.nodeMeta), ...ownedNodeMeta },
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flowPreview, liveFlow, wallColor, wallThickness, liveAttachmentsSig, flowSegmentWall]);

  /** Export to Canvas — the flow's THIRD route to the plan, and the only one that is a plain geometry write.
   *  Flow Live materialises `flowOwner` geometry for the whole graph, gated on the global Live toggle; Run
   *  Flow replays recipe OPERATIONS against a selected Space. This writes the polygons exactly as the flow
   *  computed them, in TWO stages the node exposes separately:
   *
   *   • the eye open → a PREVIEW (`flowpreview:<nodeId>:` ids, `flowOwner` set). Host-owned, written with
   *     `history.replace` so it never becomes an undo step, and rebuilt whenever the graph changes.
   *   • Commit → HANDED OVER (`flowstamp:<nodeId>:` ids, NO `flowOwner`). An ordinary undoable edit that the
   *     flow no longer tracks, so the user can move/edit/delete it freely. Committing drops this node's
   *     preview, so the two copies never coexist.
   *
   *  Idempotence comes from the id prefix rather than an ownership field, so "Replace previous" removes only
   *  what THIS node put down last time — hand-drawn geometry sharing the layer, and other Export to Canvas
   *  nodes' output, are untouched. Coordinates are world-pixel (the frame `flowPreview` items are already
   *  in), so nothing is converted on the way in. */
  const buildExportCanvasEntities = useCallback((
    args: ExportCanvasRequest,
    idPrefix: string,
    owner: string | undefined,
    layersIn: NonNullable<FloorPlanModel["layers"]>,
  ): { rooms: Room[]; walls: Wall[]; layers: NonNullable<FloorPlanModel["layers"]>; touched: Set<string> } => {
    const thicknessPx = Math.max(1, args.thickness * pixelsPerMeter);
    const slugify = (s: string) =>
      s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "flow-export";

    // Layer creation WITHOUT hijacking the active layer: one write can land on several row layers at once,
    // so there is no single sensible "now draw here" answer (cf. ensureLayerInLayers, which does switch).
    const palette = ["#ef4444", "#f97316", "#eab308", "#22c55e", "#06b6d4", "#3b82f6", "#a855f7", "#ec4899"];
    let layers = layersIn;
    const ensureStampLayer = (slug: string, name: string): string => {
      if (!layers.some((l) => l.id === slug)) {
        const order = layers.reduce((m, l) => Math.max(m, l.order), 0) + 1;
        layers = [...layers, { id: slug, name, color: palette[layers.length % palette.length], visible: true, locked: false, order }];
      }
      return slug;
    };
    const PREFIX = idPrefix;

    // Ring nesting → holes. A ring whose centroid falls inside a larger ring of the same piece is that
    // ring's hole rather than a Space of its own — the same rule the Live materialiser uses, so a poché
    // result from Boolean 2D / Graph to Openings stamps with its openings intact.
    const areaOf = (r: Point[]) => {
      let a = 0;
      for (let i = 0; i < r.length; i++) { const p = r[i], q = r[(i + 1) % r.length]; a += p.x * q.y - q.x * p.y; }
      return Math.abs(a) / 2;
    };
    const centroidIn = (r: Point[], o: Point[]) => {
      const cx = r.reduce((s, p) => s + p.x, 0) / r.length;
      const cy = r.reduce((s, p) => s + p.y, 0) / r.length;
      let inside = false;
      for (let i = 0, j = o.length - 1; i < o.length; j = i++) {
        if ((o[i].y > cy) !== (o[j].y > cy) && cx < ((o[j].x - o[i].x) * (cy - o[i].y)) / (o[j].y - o[i].y) + o[i].x) inside = !inside;
      }
      return inside;
    };

    const newRooms: Room[] = [];
    const newWalls: Wall[] = [];
    const touchedLayers = new Set<string>();

    args.pieces.forEach((piece, pi) => {
      const rawName = args.layerMode === "row" ? (piece.layer?.trim() || piece.name) : args.layerName;
      const layerId = ensureStampLayer(`stamp-${slugify(rawName)}`, rawName.trim() || "Flow Export");
      touchedLayers.add(layerId);
      const rings = piece.polygons.filter((p) => p.length >= 2);

      // Open geometry (skeleton centrelines, graph paths, dimension lines) has no interior — segments only,
      // and the run is NOT closed back to its first point.
      if (piece.openPath) {
        if (!args.makeWalls) return;
        rings.forEach((ring, ri) => {
          for (let i = 0; i < ring.length - 1; i++) {
            const a = ring[i], b = ring[i + 1];
            if (Math.hypot(b.x - a.x, b.y - a.y) < 1) continue;
            newWalls.push({
              id: `${PREFIX}${pi}:${ri}:${i}`,
              start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
              thickness: thicknessPx, color: piece.color, method: "center", layerId,
              ...(owner ? { flowOwner: owner } : {}),
            });
          }
        });
        return;
      }

      const closed = rings.filter((p) => p.length >= 3);
      const parent = closed.map((r, i) => {
        if (closed.length > 30) return -1;   // O(n²) containment — skip the nesting pass on huge results
        let best = -1, bestArea = Infinity;
        closed.forEach((o, j) => {
          if (j !== i && areaOf(o) > areaOf(r) && areaOf(o) < bestArea && centroidIn(r, o)) { best = j; bestArea = areaOf(o); }
        });
        return best;
      });

      closed.forEach((outer, ri) => {
        if (parent[ri] >= 0) return;   // a hole of another ring, not a Space in its own right
        const holes = closed.filter((_, hi) => parent[hi] === ri);
        // `outlineOnly` = a closed ring the user asked not to fill (a Render row set to "outlined"): its
        // boundary still stamps as segments, but there is no Space to create.
        if (args.makeSpaces && !piece.outlineOnly) {
          newRooms.push({
            id: `${PREFIX}${pi}:${ri}`,
            points: outer.map((p) => ({ x: p.x, y: p.y })),
            ...(holes.length ? { holes: holes.map((hr) => hr.map((p) => ({ x: p.x, y: p.y }))) } : {}),
            layerId,
            fill: piece.color, stroke: piece.color,
            fillOpacity: 0.2,
            roomType: "room", label: piece.name, showLabel: args.showLabel,
            ...(owner ? { flowOwner: owner } : {}),
          });
        }
        if (args.makeWalls) {
          [outer, ...holes].forEach((ring, hk) => {
            for (let i = 0; i < ring.length; i++) {
              const a = ring[i], b = ring[(i + 1) % ring.length];
              if (Math.hypot(b.x - a.x, b.y - a.y) < 1) continue;
              newWalls.push({
                id: `${PREFIX}${pi}:${ri}:${hk}:${i}`,
                start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
                thickness: thicknessPx, color: piece.color, method: "center", layerId,
                ...(owner ? { flowOwner: owner } : {}),
              });
            }
          });
        }
      });
    });
    return { rooms: newRooms, walls: newWalls, layers, touched: touchedLayers };
  }, [pixelsPerMeter]);

  /** Commit: hand this node's geometry over to the drawing. Written with `history.set` (an undoable step)
   *  and WITHOUT `flowOwner`, so the flow stops tracking it and the live effect above never reclaims it.
   *  The node's own eye-preview is dropped in the same write — otherwise the committed copy and the preview
   *  would sit on top of each other until the next graph change. */
  const stampFlowGeometryToCanvas = useCallback((args: ExportCanvasRequest): { spaces: number; segments: number; layers: number } => {
    const h = historyRef.current;
    const PREFIX = `${FLOW_STAMP_PREFIX}${args.stampKey}:`;
    const PREVIEW = `${FLOW_EXPORT_PREVIEW_PREFIX}${args.stampKey}:`;
    const built = buildExportCanvasEntities(args, PREFIX, undefined, h.state.layers ?? []);

    // Append keeps every press, so the ids must not collide with the previous stamp — suffix them.
    if (args.mode === "append") {
      const gen = `${Date.now().toString(36)}`;
      for (const r of built.rooms) r.id = `${r.id}:${gen}`;
      for (const w of built.walls) w.id = `${w.id}:${gen}`;
    }
    // Drop this node's live preview always; drop its previous commit only in "replace" mode.
    const dropRoom = (r: Room) => r.id.startsWith(PREVIEW) || (args.mode === "replace" && r.id.startsWith(PREFIX));
    const dropWall = (w: Wall) => w.id.startsWith(PREVIEW) || (args.mode === "replace" && w.id.startsWith(PREFIX));

    h.set({
      ...h.state,
      layers: built.layers,
      rooms: [...h.state.rooms.filter((r) => !dropRoom(r)), ...built.rooms],
      walls: [...h.state.walls.filter((w) => !dropWall(w)), ...built.walls],
    });
    // The preview effect would otherwise re-materialise the preview on the next graph change and put a
    // duplicate back on top of what was just committed. Remember the node until its geometry changes.
    exportPreviewSuppressedRef.current.set(args.stampKey, exportRequestSig(args));
    return { spaces: built.rooms.length, segments: built.walls.length, layers: built.touched.size };
  }, [buildExportCanvasEntities]);

  /** Apply: write one parameter onto the object attached to each named space — a Set Object Param node's
   *  Apply button. The FIRST flow action that edits objects already on the plan rather than adding geometry,
   *  so three things matter and all three are deliberate.
   *
   *  ONE `history.set`, not one per space. Twenty-eight plots getting a direction is a single decision, and
   *  Ctrl+Z must put every previous value back together — twenty-eight steps to undo would be unusable.
   *
   *  INDICES ARE INTO `canvasContent.spaces`, which is `visibleRooms` filtered to >= 3 points; the same list
   *  the flow was shown, so index i means the same room on both sides. Rebuilt here rather than passed in so
   *  the write resolves against the CURRENT document, and an index that no longer exists is skipped.
   *
   *  ONLY THE PARAMS OBJECT IS REPLACED. The attachment keeps its id, `t`, `flip` and everything else, and a
   *  parameter the writes do not mention is untouched — this sets a value, it does not re-attach the object. */
  const applyFlowObjectParams = useCallback((batch: { paramKey: string; writes: { kind?: "space" | "node" | "segment"; i: number; v: number | string }[] }[]): { written: number; skipped: number } => {
    const h = historyRef.current;

    // The three index spaces the flow could have addressed, each rebuilt here exactly as the
    // `canvasContent` memo built the bundle the flow saw — so index i means the same element on both
    // sides. Rebuilt rather than passed in so the write resolves against the CURRENT document, and an
    // index that no longer exists is skipped.
    //   spaces   — rooms with a real outline
    //   nodes    — `wallNodes`, whose attachments live under the node's stableKey (a wallNode is derived
    //              geometry and has nowhere to hold one itself)
    //   segments — walls, minus the room-link "connection" segments the bundle also drops
    const roomTargets = h.state.rooms.filter((r) => r.points && r.points.length >= 3);
    const wallTargets = h.state.walls.filter((w) => w.segmentType !== "connection");
    const nodeTargets = wallNodesRef.current;

    // EVERY parameter this call writes, collected per element FIRST and applied ONCE. The batch is not an
    // optimisation: React state is a snapshot, so N sequential calls each build their edit from the same
    // base and the last one silently discards the other N−1. A flow that writes a pipe's discharge and both
    // its end heads would keep only the head.
    const bucket = {
      space: new Map<number, Record<string, number | string>>(),
      node: new Map<number, Record<string, number | string>>(),
      segment: new Map<number, Record<string, number | string>>(),
    };
    let skipped = 0;
    for (const { paramKey, writes } of batch) {
      const key = paramKey.trim();
      if (!key) { skipped += writes.length; continue; }
      for (const w of writes) {
        const kind = w.kind ?? "space"; // a write from a flow saved before kinds existed is a space write
        const len = kind === "node" ? nodeTargets.length : kind === "segment" ? wallTargets.length : roomTargets.length;
        if (!Number.isInteger(w.i) || w.i < 0 || w.i >= len) { skipped += 1; continue; }
        const cur = bucket[kind].get(w.i) ?? {};
        cur[key] = w.v;
        bucket[kind].set(w.i, cur);
      }
    }

    /** Replace ONLY the params object of the first attachment — id, `t`, `flip` and every parameter the
     *  writes do not mention are untouched. This sets values; it does not re-attach the object. */
    const withParams = <A extends { params?: Record<string, number | string | boolean> }>(atts: A[] | undefined, patch: Record<string, number | string>): A[] | null => {
      if (!atts?.length) return null;
      const [att, ...rest] = atts;
      return [{ ...att, params: { ...(att.params ?? {}), ...patch } }, ...rest];
    };

    let written = 0;
    const next = { ...h.state };

    if (bucket.space.size) {
      const changed = new Map<string, Record<string, number | string>>();
      roomTargets.forEach((r, i) => { const v = bucket.space.get(i); if (v && r.attachments?.[0]) changed.set(r.id, v); });
      if (changed.size) {
        next.rooms = next.rooms.map((r) => {
          const v = changed.get(r.id);
          const atts = v ? withParams(r.attachments, v) : null;
          if (!atts) return r;
          written += Object.keys(v!).length;
          return { ...r, attachments: atts };
        });
      }
    }

    if (bucket.segment.size) {
      const changed = new Map<string, Record<string, number | string>>();
      wallTargets.forEach((w, i) => { const v = bucket.segment.get(i); if (v && w.attachments?.[0]) changed.set(w.id, v); });
      if (changed.size) {
        next.walls = next.walls.map((w) => {
          const v = changed.get(w.id);
          const atts = v ? withParams(w.attachments, v) : null;
          if (!atts) return w;
          written += Object.keys(v!).length;
          return { ...w, attachments: atts };
        });
      }
    }

    if (bucket.node.size) {
      const nm = { ...(next.nodeMeta ?? {}) };
      let touched = false;
      nodeTargets.forEach((n, i) => {
        const v = bucket.node.get(i);
        if (!v) return;
        const atts = withParams(nm[n.stableKey]?.attachments, v);
        if (!atts) return;
        nm[n.stableKey] = { ...nm[n.stableKey], attachments: atts };
        written += Object.keys(v).length;
        touched = true;
      });
      if (touched) next.nodeMeta = nm;
    }

    if (!written) return { written: 0, skipped: batch.reduce((n, b) => n + b.writes.length, 0) };
    h.set(next);
    return { written, skipped };
  }, []);

  /** The eye-open preview for every Export to Canvas node, as a COMPLETE list — a node that is hidden,
   *  unwired or deleted simply drops out of it and its geometry disappears. Written with `history.replace`
   *  so scrubbing a parameter never floods the undo stack, and tagged `flowOwner` so it stays inert to
   *  auto-room detection exactly like Flow Live's output. It is deliberately independent of the global Live
   *  toggle: the eye on the node is its own switch.
   *
   *  Called from a debounced timer in the overlay rather than straight out of a render, so it lands in a
   *  later tick than the Flow Live effect above and the two never read the same stale `historyRef` snapshot
   *  (the ref is refreshed per render, not per write). Each leaves the other's entities alone regardless —
   *  Live filters with `isMine`, this filters with `isExportPreviewEntity`. */
  const setFlowExportPreview = useCallback((requests: ExportCanvasRequest[]) => {
    const h = historyRef.current;
    const rooms: Room[] = [];
    const walls: Wall[] = [];
    let layers = h.state.layers ?? [];
    for (const req of requests) {
      // A node whose geometry is already committed stays suppressed until that geometry actually changes,
      // so Commit doesn't leave a duplicate preview sitting on top of the committed copy.
      const committedSig = exportRequestSig(req);
      if (exportPreviewSuppressedRef.current.get(req.stampKey) === committedSig) continue;
      exportPreviewSuppressedRef.current.delete(req.stampKey);
      const owner = `${FLOW_EXPORT_PREVIEW_PREFIX}${req.stampKey}`;
      const built = buildExportCanvasEntities(req, `${owner}:`, owner, layers);
      rooms.push(...built.rooms);
      walls.push(...built.walls);
      layers = built.layers;
    }
    // Signature guard: identical geometry → no write at all, so this effect can run on every graph tick.
    const sig = [
      ...rooms.map((r) => `${r.id}#${r.points.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join("|")}`),
      ...walls.map((w) => `${w.id}@${w.start.x.toFixed(1)},${w.start.y.toFixed(1)}`),
    ].join(";");
    const had = h.state.rooms.some(isExportPreviewEntity) || h.state.walls.some(isExportPreviewEntity);
    if (sig === exportPreviewSigRef.current && had === (rooms.length > 0 || walls.length > 0)) return;
    exportPreviewSigRef.current = sig;
    h.replace({
      ...h.state,
      layers,
      rooms: [...h.state.rooms.filter((r) => !isExportPreviewEntity(r)), ...rooms],
      walls: [...h.state.walls.filter((w) => !isExportPreviewEntity(w)), ...walls],
    });
  }, [buildExportCanvasEntities]);

  /** Per-piece lengths in metres (used when splitMode === "length"). */
  const [splitLengths, setSplitLengths] = useState<number[]>([2]);
  /** "normal" runs the existing N-piece split; "strip" generates exactly two parallel cuts
   *  whose offset along the splitting axis equals splitStripLength metres, centred per splitStripPosition%. */
  const [splitType, setSplitType] = useState<"normal" | "strip">("normal");
  const [splitStripLength, setSplitStripLength] = useState<number>(2);
  const [splitStripPosition, setSplitStripPosition] = useState<number>(50);
  const [splitLive, setSplitLive] = useState<boolean>(false);
  /** When true, the split runner sets its stacking axis to the polygon's MAJOR principal axis,
   *  so cut lines run along the MINOR principal axis. Result: long rooms become a row of normal-aspect
   *  children (no long thin slices). Falls back to the manual splitAngle when the polygon is near-isotropic. */
  const [splitAlongMinorPrincipalAxis, setSplitAlongMinorPrincipalAxis] = useState<boolean>(false);
  const selectedRoomIdRef = useRef<string | null>(null);
  const visibleRoomsRef = useRef<Room[]>([]);

  /** Inset Polygon state — per-room so two rooms can carry their own setback arrays without stomping
   *  each other when the user switches selection. The keys are room ids; the value array length tracks
   *  that room's segment count. The legacy `insetSetbacks` / `insetSetAll` identifiers below are
   *  derived views of the selected room's slice for back-compat with existing readers. */
  const [insetSetbacksByRoom, setInsetSetbacksByRoom] = useState<Record<string, number[]>>({});
  const [insetSetAllByRoom, setInsetSetAllByRoom] = useState<Record<string, number>>({});
  const [insetLive, setInsetLive] = useState<boolean>(false);

  /** Shared "live preview polygon" per room, written by Inset's silent path so downstream live tools
   *  (currently Optimise Rectangle) can use the inset polygon as their working shape. Null = no live
   *  preview, fall back to room.points. */
  const livePreviewPolygonRef = useRef<Record<string, Point[] | null>>({});
  /** Recipe-driven setbacks override: when set, runRoomInset uses these instead of the insetSetbacks
   *  state, side-stepping the selection-changed useEffect race that resets per-edge values to zero on
   *  the same commit cycle as Apply-JSON's setInsetSetbacks call. Cleared after the runner consumes it. */
  const insetSetbacksOverrideRef = useRef<number[] | null>(null);
  /** Per-room shrunken polygon outline written by Optimise Rectangle's shrink-to-target search.
   *  Rendered as a dashed red overlay so the user sees how the source polygon was clipped before the
   *  inscribed rectangle was fit. Null = no shrink active for this room. */
  const shrinkPreviewPolyRef = useRef<Record<string, Point[] | null>>({});
  /** Per-room total area (m²) of the optimise-rect output: union polygon area when union mode is on,
   *  otherwise the sum of all placed rectangles. Rendered as a Live overlay label on the canvas. */
  const optimiseTotalAreaRef = useRef<Record<string, number | null>>({});
  /** Snapshot of the original wall before "Add Openings" Live mode replaces it, so we can restore on cancel. */
  const openingSourceRef = useRef<Wall | null>(null);
  // Forward-call ref for the inset → optimise-rect cascade. Populated by a useEffect after
  // runRoomOptimiseRect is declared (it's defined later in this function — using it directly in the
  // inset live useEffect would hit a temporal dead zone).
  const optimiseRectRunnerRef = useRef<((room: { id: string; points: Point[] }, silent: boolean) => boolean) | null>(null);
  /** Per-room live-preview polygon of the Optimise Rectangle Union output (bounding box of the union).
   *  Downstream tools (currently BSP) use this as their working polygon when Inset+Optimise are both Live. */
  const optimiseUnionPolygonRef = useRef<Record<string, Point[] | null>>({});
  /** Flow per-piece preview: when a Split node feeds a downstream tool from one piece handle, the
   *  Split op publishes that piece's polygon here so the downstream tool (Optimise Rect, etc.)
   *  previews fitted INSIDE the chosen piece — not the whole split. Cleared each preview run. */
  const flowPiecePolygonRef = useRef<Record<string, Point[] | null>>({});
  /** Single "working polygon" threaded through a Flow pipeline in execution order. Each tool, while
   *  `flowChainActiveRef` is on (preview), reads this as its INPUT (falling back to the room polygon)
   *  and writes its OUTPUT here for the next tool. This is what makes the pipeline strictly
   *  sequential — Optimise→Inset insets the optimise output; Inset→Optimise optimises the inset —
   *  without the ambiguity of tool-specific cascade refs reading each other. */
  const flowWorkRef = useRef<Record<string, Point[] | null>>({});
  const flowChainActiveRef = useRef<boolean>(false);
  /** Bumped by writers of livePreviewPolygonRef so React effects can rewatch and re-run. */
  const [livePreviewTick, setLivePreviewTick] = useState<number>(0);

  /** Foldable section expansion state (properties-tab blocks). */
  const [splitExpanded, setSplitExpanded] = useState<boolean>(false);
  const [insetExpanded, setInsetExpanded] = useState<boolean>(false);
  // Inset Polygon → offset direction. true (default) = offset inward (classic inset);
  // false = offset the polygon outward by the setback distance. Lifted so runRoomInset
  // and the canvas overlay agree on the direction.
  const [insetInside, setInsetInside] = useState<boolean>(true);
  // Inset Polygon → Deduct Area UI state (lifted from InsetPolygonBlock so the canvas can render it).
  const [insetDeductEnabled, setInsetDeductEnabled] = useState<boolean>(false);
  const [insetDeductMode, setInsetDeductMode] = useState<"area" | "percent">("area");
  const [insetDeductAreaM2, setInsetDeductAreaM2] = useState<number>(0);
  const [insetDeductPercent, setInsetDeductPercent] = useState<number>(0);
  const [insetDeductAngle, setInsetDeductAngle] = useState<number>(0);
  // Inset Polygon → Mode + Front/Remaining values (lifted so the BUA Calculator's
  // Show on Canvas can drive the block straight into Front-And-Remaining mode).
  const [insetMode, setInsetMode] = useState<"equal" | "variable" | "front-remaining">("variable");
  const [insetFrontVal, setInsetFrontVal] = useState<number>(0);
  const [insetRemainingVal, setInsetRemainingVal] = useState<number>(0);
  const [massingExpanded, setMassingExpanded] = useState<boolean>(false);
  const [massingAvgWidth, setMassingAvgWidth] = useState<number>(3.5);
  const [massingLive, setMassingLive] = useState<boolean>(false);
  const [massingFloorsFromFsi, setMassingFloorsFromFsi] = useState<boolean>(false);
  const [massingShowBlocks, setMassingShowBlocks] = useState<boolean>(false);
  const [massingExtrudeUpwards, setMassingExtrudeUpwards] = useState<boolean>(true);
  const [pathSetterExpanded, setPathSetterExpanded] = useState<boolean>(false);
  const [openingExpanded, setOpeningExpanded] = useState<boolean>(false);
  const [openingLength, setOpeningLength] = useState<number>(1.0);
  const [openingPos, setOpeningPos] = useState<number>(50);
  const [openingLive, setOpeningLive] = useState<boolean>(false);

  const [optimiseExpanded, setOptimiseExpanded] = useState<boolean>(false);
  const [classifyExpanded, setClassifyExpanded] = useState<boolean>(false);
  const [optimiseLive, setOptimiseLive] = useState<boolean>(false);
  const [optLShapeExpanded, setOptLShapeExpanded] = useState<boolean>(false);
  const [optLShapeLive, setOptLShapeLive] = useState<boolean>(false);
  const [optLShapeAxisAngle, setOptLShapeAxisAngle] = useState<number>(0);
  const [optShapeKind, setOptShapeKind] = useState<OptimiseShapeKind>("lshape");
  /** Iterative packing: place N rectangles greedily. */
  const [maxRectCount, setMaxRectCount] = useState<number>(1);
  const [maxRectMinArea, setMaxRectMinArea] = useState<number>(0.1);
  /** Union: emit only the union polyomino's boundary instead of N separate rectangles. */
  const [maxRectUnion, setMaxRectUnion] = useState<boolean>(false);
  /** Axis-tilt angle (degrees, 0-179) — used when reference is "custom" or an edge. */
  const [maxRectAxisAngle, setMaxRectAxisAngle] = useState<number>(0);
  /** Reference selector: "none" = any-angle search (free orientation per rectangle);
   *  "custom" = user-driven axis-tilt slider; number = polygon edge index (axis tilt = edge angle). */
  const [maxRectReference, setMaxRectReference] = useState<"none" | "custom" | number>("custom");
  /** Shape mode: "rectangle" (independent width × height), "square" (width = height), or "hexagon" (regular
   *  6-gon packed on a lattice). */
  const [maxRectShape, setMaxRectShape] = useState<"rectangle" | "square" | "hexagon" | "lshape">("rectangle");
  /** Optimise-Rect target area (m²) + tilt — bisects the union polygon into a green sub-polygon
   *  equal to target and a red remainder. Independent Live toggle and per-room committed entries
   *  mirror the Fill Area block, so the overlay can persist after the OptRect block's main Live
   *  is unchecked. */
  const [maxRectTargetArea, setMaxRectTargetArea] = useState<number>(50);
  const [maxRectTargetTilt, setMaxRectTargetTilt] = useState<number>(0);
  const [maxRectTargetLive, setMaxRectTargetLive] = useState<boolean>(false);
  /** When on, the target-area slider in OptimiseRectangleBlock is hidden and `maxRectTargetArea`
   *  is auto-driven by (GCR % × site area) sourced from the plot-boundary INPUTS block. */
  const [maxRectTargetFromGcr, setMaxRectTargetFromGcr] = useState<boolean>(false);
  const [maxRectTargetByRoom, setMaxRectTargetByRoom] = useState<Record<string, { target: number; tilt: number }>>({});
  /** Shrink-to-target: when enabled, the runner clips the room polygon with a half-plane perpendicular
   *  to `maxRectShrinkAngle` and binary-searches the cut distance until the largest inscribed rect's
   *  area matches `maxRectTargetArea`. Preview-only — original room polygon stays intact on commit. */
  const [maxRectShrinkEnabled, setMaxRectShrinkEnabled] = useState<boolean>(true);
  const [maxRectShrinkAngle, setMaxRectShrinkAngle] = useState<number>(0);
  /** Manual shrink-slide position (0–100): percentage along the shrink-angle direction at which the
   *  cut line sits. 0 = no clip, 100 = fully clipped away. Always drives the cut when shrink is on. */
  const [maxRectShrinkSlide, setMaxRectShrinkSlide] = useState<number>(0);
  /** Optimise-shrink: when ticked, the runner overrides the manual slide and binary-searches the cut
   *  position along `shrinkAngle` until the multi-rect total (packing area) is ≤ targetArea. */
  const [maxRectOptimiseShrinkEnabled, setMaxRectOptimiseShrinkEnabled] = useState<boolean>(true);
  /** Post-scale placed rectangle(s) about their union centroid so the total area
   *  exactly matches `maxRectTargetArea`. Off by default — preserves the strict
   *  inscribed-rectangle behaviour. When on, the rectangles may protrude past the
   *  shrunk polygon by a small percentage of their dimensions. */
  const [maxRectExactArea, setMaxRectExactArea] = useState<boolean>(false);
  /** Auto-found slide percentage written by Optimise-shrink's search. Surfaced in the UI as a
   *  read-only display so the user sees the converged shrink amount. */
  const [maxRectSolvedShrinkSlide, setMaxRectSolvedShrinkSlide] = useState<number>(0);
  /** Monotonic counter — bumped by Apply-JSON's `pickVariation: true` directive on
   *  optimise-rect, opens the layout-variations modal inside OptimiseRectangleBlock
   *  without simulating a button click. */
  const [optRectVariationsOpenTick, setOptRectVariationsOpenTick] = useState<number>(0);

  /** Place Object Along Boundary — multi-object state, keyed per room. */
  const [placedObjectsByRoom, setPlacedObjectsByRoom] = useState<Record<string, PlacedObject[]>>({});
  /** Seed per room driving deterministic random positions for unlocked objects. */
  const [placementSeedByRoom, setPlacementSeedByRoom] = useState<Record<string, number>>({});
  const [placeLive, setPlaceLive] = useState<boolean>(false);
  const [placeExpanded, setPlaceExpanded] = useState<boolean>(false);
  /** Object id of the currently-dragged placement rectangle — drives the panel-row highlight + scroll-into-view. */
  const [highlightedPlacementObjectId, setHighlightedPlacementObjectId] = useState<string | null>(null);

  /** Visibility Polygon state — mode, viewer point, edge index, computed polygons cache, expand/live. */
  const [visibilityModeByRoom, setVisibilityModeByRoom] = useState<Record<string, "point" | "segment">>({});
  const [visibilityViewerByRoom, setVisibilityViewerByRoom] = useState<Record<string, Point>>({});
