  const [visibilityPolygonsByRoom, setVisibilityPolygonsByRoom] = useState<Record<string, Point[][]>>({});
  const [visibilityExpanded, setVisibilityExpanded] = useState<boolean>(false);
  const [visibilityLive, setVisibilityLive] = useState<boolean>(false);
  /** Monte-Carlo light-tracing parameters (point mode only). Bounces=0 means "off" (just direct visibility). */
  const [visibilityBouncesByRoom, setVisibilityBouncesByRoom] = useState<Record<string, number>>({});
  const [visibilityRayCountByRoom, setVisibilityRayCountByRoom] = useState<Record<string, number>>({});
  const [visibilityReflectivityByRoom, setVisibilityReflectivityByRoom] = useState<Record<string, number>>({});
  const [visibilityRaysByRoom, setVisibilityRaysByRoom] = useState<Record<string, Array<{ x1: number; y1: number; x2: number; y2: number; energy: number }>>>({});

  /** Voronoi Seeds state. Seeds keyed by room id so selection can restore. */
  const [voronoiSeedsByRoom, setVoronoiSeedsByRoom] = useState<Record<string, Point[]>>({});
  /** When set, the Voronoi seeds for that room mirror the polygon's vertices and re-sync
   *  whenever the polygon's shape changes. */
  const [voronoiUseVerticesByRoom, setVoronoiUseVerticesByRoom] = useState<Record<string, boolean>>({});

  /** Whenever any room has Voronoi "Use vertices" enabled, keep its seeds in lockstep with the
   *  polygon's vertices — so reshaping the room (move vertex, inset, etc.) re-snaps the seeds. */
  useEffect(() => {
    const flags = voronoiUseVerticesByRoom;
    if (!Object.values(flags).some(Boolean)) return;
    setVoronoiSeedsByRoom((prev) => {
      let changed = false;
      const next: Record<string, Point[]> = { ...prev };
      for (const room of history.state.rooms) {
        if (!flags[room.id]) continue;
        const verts = room.points.map((q) => ({ x: q.x, y: q.y }));
        const cur = prev[room.id] ?? [];
        const same = cur.length === verts.length && cur.every((s, i) => s.x === verts[i].x && s.y === verts[i].y);
        if (same) continue;
        next[room.id] = verts;
        changed = true;
      }
      return changed ? next : prev;
    });
  }, [voronoiUseVerticesByRoom, history.state.rooms]);
  const [voronoiLive, setVoronoiLive] = useState<boolean>(false);
  const [voronoiExpanded, setVoronoiExpanded] = useState<boolean>(false);
  const [voronoiMetric, setVoronoiMetric] = useState<"euclidean" | "manhattan" | "chebyshev">("euclidean");
  /** When true, runRoomVoronoi keeps only the edges along the longest path in the
   *  internal-edge graph of the Voronoi partition — i.e. the medial-axis backbone /
   *  centerline of the polygon. The rest of the cell boundaries are discarded. */
  const [voronoiFilterLongestPath, setVoronoiFilterLongestPath] = useState<boolean>(false);
  /** Voronoi recursion depth when "Use vertices" is on: at level N the
   *  Voronoi is re-computed N times, each pass replacing seeds with the
   *  cell-vertices produced by the previous pass. 1 = single pass. Only
   *  applies to the Euclidean metric (Manhattan/Chebyshev are raster-based
   *  and don't expose cell vertices). */
  const [voronoiLevel, setVoronoiLevel] = useState<number>(1);

