    /** Words that should all appear (case-insensitive) for this command to be a candidate — supports fuzzy ordering. */
    keywords: string[];
    /** Regex to extract params from the actual prompt. Captures map to named params. */
    match: RegExp;
    /** Build the operation given the regex match groups. */
    build: (m: RegExpMatchArray) => { tool: string; params: Record<string, unknown> } | null;
